  '[[\'Switch to Free Plus?\\n' => '[[\'Перейти на Free Plus?\\n',
  '\\nYour Pro activation code will be removed from this site. Pro add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.\\n' => '\\nВаш код активации Pro будет удален с этого сайта. Дополнения Pro будут недоступны, пока вы не обновите их снова. Ваши формы, записи и настройки не будут удалены.\\n',
  '\\nSwitch to Free?\\n' => '\\nПерейти на бесплатную версию?\\n',
