  '[[\'Checking email delivery...\\n' => '[[\'Проверка доставки электронной почты...\\n',
  '\\nA test email was sent. Waiting for delivery confirmation...\\n' => '\\nОтправлено тестовое письмо. Ожидание подтверждения доставки...\\n',
  '\\nEmail delivery is ready. Form notifications can be sent.\\n' => '\\nДоставка по электронной почте готова. Уведомления в форме можно отправлять.\\n',
