  '[[\'We could not verify delivery. Your email address was saved; please check your mail configuration in General Settings.\\n' => '[[\'Нам не удалось проверить доставку. Ваш адрес электронной почты был сохранен; пожалуйста, проверьте конфигурацию вашей почты в общих настройках.\\n',
