  '\\nYour security session has expired or is invalid. Please refresh the page. E403\\n' => '\\nВаш сеанс безопасности истек или недействителен. Пожалуйста, обновите страницу. E403\\n',
  '\\nYour security session has expired or is invalid. Please refresh the page. E400\\n' => '\\nВаш сеанс безопасности истек или недействителен. Пожалуйста, обновите страницу. E400\\n',
  '\\nThis is a private form. Please log in to access it.\\n' => '\\nЭто частная форма. Пожалуйста, войдите, чтобы получить к нему доступ.\\n',
  '\\nPlease check the site key and secret key on Flux Forms panel > Settings > Google Keys to resolve the error.\', \'en\']]' => '\\nЧтобы устранить ошибку, проверьте ключ сайта и секретный ключ на панели Flux Forms > Настройки > Google Keys.\', \'en\']]',
  '\\nThere seems to be a problem with the Captcha. Please try again.\\n' => '\\nПохоже, возникла проблема с капчей. Пожалуйста, попробуйте еще раз.\\n',
  '\\nYour account has been successfully created! You will receive an email containing your information\\n' => '\\nВаша учетная запись успешно создана! Вы получите электронное письмо с вашей информацией\\n',
  '\\nThis username or password combination is incorrect.\\n' => '\\nЭта комбинация имени пользователя и пароля неверна.\\n',
  '\\nIf your email is valid, a new password will send to your email.\\n' => '\\nЕсли ваш адрес электронной почты действителен, на него будет отправлен новый пароль.\\n',
  '\\nThe survey has been successfully completed.\\n' => '\\nОпрос успешно завершен.\\n',
  '\\nSurvey Results Display\\n' => '\\nОтображение результатов опроса\\n',
  '\\nDo not show results\\n' => '\\nНе показывать результаты\\n',
  '\\nShow results with bar chart\\n' => '\\nПоказать результаты с помощью гистограммы\\n',
  '\\nShow results with pie chart\\n' => '\\nПоказать результаты с помощью круговой диаграммы\\n',
  '\\nAfter submission, visitors can see aggregate survey results\\n' => '\\nПосле отправки посетители могут увидеть совокупные результаты опроса.\\n',
  '\\nShow this field in public survey results\\n' => '\\nПоказывать это поле в результатах общественного опроса\\n',
  '\\nSurvey Results\\n' => '\\nРезультаты опроса\\n',
  '\\nWe are sorry, but there seems to be a security error (405) with your request.\\n' => '\\nПриносим извинения, но, похоже, в вашем запросе произошла ошибка безопасности (405).\\n',
  '\\nError, Setting not Found\\n' => '\\nОшибка, настройка не найдена\\n',
  '\\nSorry, there seems to be an error. Please verify that you are human and try again.\\n' => '\\nИзвините, похоже, произошла ошибка. Пожалуйста, подтвердите, что вы человек, и повторите попытку.\\n',
  '\\nPlease enter valid values\\n' => '\\nПожалуйста, введите действительные значения\\n',
  '\\nInvalid Confirmation Code.\\n' => '\\nНеверный код подтверждения.\\n',
  '\\nThere seems to be an error with the file permissions.\\n' => '\\nПохоже, произошла ошибка с правами доступа к файлу.\\n',
  '\\nOops! Something went wrong. Please try refreshing the page and try again.\\n' => '\\nУпс! Что-то пошло не так. Пожалуйста, попробуйте обновить страницу и повторите попытку.\\n',
  '[[\'HTML tags are not allowed.\\n' => '[[\'Теги HTML не разрешены.\\n',
  '\\nYour message has been sent.\\n' => '\\nВаше сообщение отправлено.\\n',
  '\\nWe have received your message.\\n' => '\\nМы получили ваше сообщение.\\n',
  '\\nThe form has been submitted successfully\\n' => '\\nФорма успешно отправлена\\n',
  '\\nYour registration is successful.\\n' => '\\nВаша регистрация прошла успешно.\\n',
  'Welcome' => 'Добро пожаловать',
  '\\nYou have successfully subscribed. Thank you!\\n' => '\\nВы успешно подписались. Спасибо!\\n',
  '\\nThank You for taking the time to complete this survey.\\n' => '\\nСпасибо, что нашли время заполнить этот опрос.\\n',
  '\\nPlease go to Panel > Settings > Email Settings, click "Check Email Server", then click "Save".\\n' => '\\nПерейдите в Панель > Настройки > Настройки электронной почты, нажмите «Проверить сервер электронной почты», затем нажмите «Сохранить».\\n',
  '\\nUh oh, looks like there is a problem with the form. Please make sure all of the input is correct.\\n' => '\\nОй, похоже, проблема с формой. Пожалуйста, убедитесь, что все введенные данные верны.\\n',
  '\\nThe form was not created\\n' => '\\nФорма не была создана\\n',
  '\\nScripts tags are not allowed.\\n' => '\\nТеги сценариев не разрешены.\\n',
  '\\nBootstrap Template\\n' => '\\nШаблон начальной загрузки\\n',
  '\\nWarning: If your theme uses Bootstrap, make sure the option below is enabled.\\n' => '\\nВнимание: если ваша тема использует Bootstrap, убедитесь, что опция ниже включена.\\n',
  '\\nMy theme is based on Bootstrap\\n' => '\\nМоя тема основана на Bootstrap\\n',
  '\\nUh oh, it looks like there is a problem with your request. Please review everything and try again.\\n' => '\\nОй, похоже, с вашим запросом возникла проблема. Пожалуйста, просмотрите все и повторите попытку.\\n',
  'updated' => 'обновлено',
  '\\nPlease type in your message\', \'en\']]' => '\\nПожалуйста, введите ваше сообщение\', \'ru\']]',
  '\\nThe files have been deleted.\\n' => '\\nФайлы были удалены.\\n',
  '\\nThe activation code you entered is incorrect. Please double-check and try again.\\n' => '\\nВведенный вами код активации неверен. Пожалуйста, проверьте еще раз и повторите попытку.\\n',
  '\\nWe are sorry, but the message was not sent due to a settings error. Please contact the admin for assistance.\\n' => '\\nПриносим извинения, но сообщение не было отправлено из-за ошибки в настройках. Пожалуйста, обратитесь к администратору за помощью.\\n',
  '\\nOR\\n' => '\\nИЛИ\\n',
  '\\nEmail Template\\n' => '\\nШаблон электронной почты\\n',
  '\\nreset\\n' => '\\nсброс\\n',
  '\\nNot Found\\n' => '\\nНе найден\\n',
  '\\nEditor\\n' => '\\nРедактор\\n',
  '\\nPlease add the shortcode_message shortcode to the email template.\\n' => '\\nПожалуйста, добавьте короткий код shortcode_message в шаблон электронного письма.\\n',
  '\\nYour Email Template cannot exceed 10,000 characters.\\n' => '\\nВаш шаблон электронной почты не может превышать 10 000 символов.\\n',
  '\\nPlease use HTML tags to create your email template.\\n' => '\\nДля создания шаблона электронной почты используйте HTML-теги.\\n',
  '\\nAdd this shortcode inside a tag to display the title of the email.\\n' => '\\nДобавьте этот короткий код в тег, чтобы отобразить заголовок электронного письма.\\n',
  '\\nAdd this shortcode inside an HTML tag to display the message content of an email.\\n' => '\\nДобавьте этот короткий код в тег HTML, чтобы отобразить содержимое сообщения электронной почты.\\n',
  '\\nTo display the website name, add this shortcode inside an HTML tag.\\n' => '\\nЧтобы отобразить название веб-сайта, добавьте этот короткий код в HTML-тег.\\n',
  '\\nAdd this shortcode within an HTML tag to display the Website URL.\\n' => '\\nДобавьте этот короткий код в тег HTML, чтобы отобразить URL-адрес веб-сайта.\\n',
  '\\nYou can display the Admin Email address of your WordPress site by adding this shortcode within an HTML tag.\\n' => '\\nВы можете отобразить адрес электронной почты администратора вашего сайта WordPress, добавив этот короткий код в HTML-тег.\\n',
