  '\\nInstall the add-on\\n' => '\\nУстановите дополнение\\n',
  '\\nPlease go to the Add-ons Page of Flux Forms plugin and install the Jalili date addons\\n' => '\\nПерейдите на страницу дополнений плагина Flux Forms и установите дополнения к дате Jalili.\\n',
  '\\nPlease go to the Add-ons Page of Flux Forms plugin and install the Hijri date addons\\n' => '\\nПерейдите на страницу дополнений плагина Flux Forms и установите дополнения к дате Хиджры.\\n',
  'warning' => 'предупреждение',
  '\\ndate & time\\n' => '\\nдата и время\\n',
  '\\nEnable file upload in the response box\\n' => '\\nВключить загрузку файлов в поле ответа\\n',
  '\\nEnable Google reCAPTCHA in the response box\\n' => '\\nВключите Google reCAPTCHA в поле ответа\\n',
