  '\\nConditional logic Add-on\\n' => '\\nДополнение условной логики\\n',
  '\\nThe Conditional Logic Add-on enables dynamic and interactive forms based on specific user inputs or conditional rules. It allows for highly personalized forms tailored to meet users’ unique needs.\\n' => '\\nДополнение условной логики позволяет создавать динамические и интерактивные формы на основе определенных пользовательских данных или условных правил. Он позволяет создавать высоко персонализированные формы, отвечающие уникальным потребностям пользователей.\\n',
  '\\nThe Conditional Logic module failed to load. Please refresh the page; if the problem continues, deactivate and reactivate the Conditional Logic add-on.\\n' => '\\nНе удалось загрузить модуль условной логики. Пожалуйста, обновите страницу; если проблема не исчезнет, деактивируйте и повторно активируйте надстройку «Условная логика».\\n',
