  '\\nSMS Notifications\\n' => '\\nSMS-уведомления\\n',
  '\\nEnter the administrators’ mobile numbers to receive SMS notifications, such as alerts or new messages.\\n' => '\\nВведите номера мобильных телефонов администраторов, чтобы получать SMS-уведомления, например оповещения или новые сообщения.\\n',
  '[[\'All SMS notifications sent by Flux Forms will be delivered to the numbers entered here.\\n' => '[[\'Все SMS-уведомления, отправленные Flux Forms, будут доставлены на введенные здесь номера.\\n',
