  '\\nThe recording is longer than the allowed duration.\\n' => '\\nПродолжительность записи превышает допустимую.\\n',
  '\\nRecording Quality\\n' => '\\nКачество записи\\n',
  '\\nMax Duration (seconds)\\n' => '\\nМаксимальная продолжительность (секунды)\\n',
  'Low' => 'Низкий',
