  '\\n720p (HD)\\n' => '\\n720p (HD)\\n',
  '\\n1080p (Full HD)\\n' => '\\n1080p (Full HD)\\n',
  '\\nPermission to access your microphone/camera/screen was denied.\\n' => '\\nВ доступе к вашему микрофону/камере/экрану было отказано.\\n',
  '\\nYour browser does not support this recording feature.\\n' => '\\nВаш браузер не поддерживает эту функцию записи.\\n',
  '\\nMaximum recording duration reached.\\n' => '\\nДостигнута максимальная продолжительность записи.\\n',
  '\\nMade by Flux Forms\\n' => '\\nСделано Flux Forms\\n',
  '\\nTap to start recording\\n' => '\\nНажмите, чтобы начать запись\\n',
  '\\nDownload recording\\n' => '\\nЗагрузить запись\\n',
  '\\nRecording requires a secure (HTTPS) connection. Please ask the site administrator to enable HTTPS on this host.\\n' => '\\nДля записи требуется безопасное соединение (HTTPS). Попросите администратора сайта включить HTTPS на этом хосте.\\n',
  '\\nScreen recording is not supported on this device or browser (most mobile browsers do not allow it). Please open the form in a desktop browser such as Chrome, Edge or Firefox.\\n' => '\\nЗапись экрана не поддерживается на этом устройстве или в браузере (большинство мобильных браузеров не поддерживают это). Откройте форму в браузере на рабочем столе, например Chrome, Edge или Firefox.\\n',
  '\\nCountdown before recording\\n' => '\\nОбратный отсчет перед записью\\n',
  '\\nDefault camera (mobile)\\n' => '\\nКамера по умолчанию (мобильная)\\n',
