  '\\nLet the user download a copy of the recording\\n' => '\\nРазрешить пользователю загрузить копию записи\\n',
  '\\nYour hosting accepts uploads up to%sMB.\\n' => '\\nВаш хостинг принимает загрузки размером до%sМБ.\\n',
