  '\\nNo data available for this period\\n' => '\\nНет данных за этот период\\n',
  '\\nThe entered data does not match the form type. If you are an admin, please review the form type.\', \'en\']]' => '\\nВведенные данные не соответствуют типу формы. Если вы являетесь администратором, проверьте тип формы.\', \'en\']]',
  '\\nError: Please ensure there is only one form per page.\\n' => '\\nОшибка: убедитесь, что на странице имеется только одна форма.\\n',
  '\\nYour activation code has been verified. Enjoy all Pro features of Flux Forms.", \'en\']]' => '\\nВаш код активации проверен. Наслаждайтесь всеми функциями Flux Forms Pro.", \'en\']]',
  '\\nThe confirmation code for this message is%s. By clicking the button below, you will be able to track messages and view received responses. If needed, you can also send a new reply.\\n' => '\\nКод подтверждения для этого сообщения:%s. Нажав кнопку ниже, вы сможете отслеживать сообщения и просматривать полученные ответы. При необходимости вы также можете отправить новый ответ.\\n',
  '\\nTo explore the full functionality and settings of Flux Forms, including email configurations, form creation options, and other features, simply delve into our%1$sdocumentation%2$s.\\n' => '\\nЧтобы изучить все функциональные возможности и настройки Flux Forms, включая настройки электронной почты, параметры создания форм и другие функции, просто воспользуйтесь нашей документацией%1$s%2$s.\\n',
  '\\nResponses & Confirmation\\n' => '\\nОтветы и подтверждение\\n',
  '\\nTest emails may land in your spam folder. If emails are not delivered, this is usually related to your hosting or email server configuration.server settings%1$sLearn how to fix email delivery issues%2$sor%3$scontact Flux Forms support%4$s.\\n' => '\\nТестовые письма могут попасть в папку со спамом. Если электронные письма не доставляются, это обычно связано с конфигурацией вашего хостинга или почтового сервера. Настройки сервера%1$sУзнайте, как устранить проблемы с доставкой электронной почты%2$sили%3$sОбратитесь в службу поддержки Flux Forms%4$s.\\n',
  '\\nFrom Address\\n' => '\\nОт адреса\\n',
  '\\nMake sure this email address matches the one configured in your SMTP settings to prevent email delivery issues.\\n' => '\\nУбедитесь, что этот адрес электронной почты соответствует адресу, указанному в настройках SMTP, чтобы предотвратить проблемы с доставкой электронной почты.\\n',
  '\\nTo preview the form, you need to save the built form and try again.\\n' => '\\nЧтобы просмотреть форму, необходимо сохранить созданную форму и повторить попытку.\\n',
  '\\nNo selected rows found.\\n' => '\\nВыбранные строки не найдены.\\n',
  '\\nMark as Read\\n' => '\\nОтметить как прочитанное\\n',
  '\\nRequire admin login to view responses\\n' => '\\nДля просмотра ответов требуется вход администратора\\n',
  '\\nDevelopment Mode (Sandbox)\\n' => '\\nРежим разработки (песочница)\\n',
  '\\nWhen enabled, uses sandbox/demo servers for PayPal and other services. Disable for production.\\n' => '\\nЕсли этот параметр включен, используются песочницы/демо-серверы для PayPal и других сервисов. Отключить для производства.\\n',
  '\\nAfter changing the Development Mode (Sandbox) option, save the settings, then deactivate and reactivate Flux Forms plugin from the Plugins page for the changes to take effect.\\n' => '\\nПосле изменения параметра «Режим разработки (песочница)» сохраните настройки, затем деактивируйте и повторно активируйте плагин Flux Forms на странице «Плагины», чтобы изменения вступили в силу.\\n',
  '\\nI have read and agree to%1$sthe terms and conditions%2$s\\n' => '\\nЯ прочитал%1$sусловия использования%2$sи согласен с ними \\n',
  '\\nTerms\\n' => '\\nУсловия\\n',
  '\\nPreview in new tab\\n' => '\\nПредварительный просмотр в новой вкладке\\n',
  '\\nMaximum date\\n' => '\\nМаксимальная дата\\n',
  '\\nMinimum date\\n' => '\\nМинимальная дата\\n',
  '\\nValid formats:%s\\n' => '\\nДействительные форматы:%s\\n',
  '\\nZoom\\n' => '\\nМасштаб\\n',
  '\\nThe map library (OpenStreetMap and Leaflet) loads only on pages that contain a location picker field.\\n' => '\\nБиблиотека карт (OpenStreetMap и Leaflet) загружается только на страницах, содержащих поле выбора местоположения.\\n',
  '\\nEnable Location Picker in Flux Forms\\n' => '\\nВключить выбор местоположения в формах Flux\\n',
  '\\nFlux Forms cannot display the form because jQuery is not properly loaded. This issue might be due to incorrect jQuery invocation by another plugin or the current website theme.\\n' => '\\nFlux Forms не может отобразить форму, поскольку jQuery загружен неправильно. Эта проблема может быть связана с неправильным вызовом jQuery другим плагином или текущей темой веб-сайта.\\n',
  '\\nTelegram Notification Add-on\\n' => '\\nДополнение для уведомлений Telegram\\n',
  '\\nThe Telegram notification add-on lets you get notifications on your Telegram app whenever you receive new messages or responses\\n' => '\\nДополнение уведомлений Telegram позволяет вам получать уведомления в приложении Telegram всякий раз, когда вы получаете новые сообщения или ответы.\\n',
  '\\nEnter a location name\\n' => '\\nВведите название местоположения\\n',
  '\\nThe%1$spages are currently unavailable. It looks like another plugin is causing a conflict with%1$s. To fix this issue,%2$scontact%1$ssupport%3$sfor assistance or try disabling your plugins one at a time to identify the one causing the conflict.\\n' => '\\nСтраницы%1$sв настоящее время недоступны. Похоже, другой плагин вызывает конфликт с%1$s. Чтобы устранить эту проблему,%2$sобратитесь в службу поддержки%1$s%3$sза помощью или попробуйте отключить плагины по одному, чтобы определить тот, который вызывает конфликт.\\n',
  'Settings' => 'Настройки',
  '[[\'Send email with submitted form content only\\n' => '[[\'Отправлять электронное письмо только с отправленным содержимым формы\\n',
  '\\n%scopied!\\n' => '\\n%sскопировано!\\n',
  '\\nThe website is not responding; please refresh and try again—saving or submitting is not available until it is restored.\\n' => '\\nВеб-сайт не отвечает; обновите страницу и повторите попытку — сохранение или отправка будут недоступны до тех пор, пока они не будут восстановлены.\\n',
  '\\nYour session has expired or is no longer valid. Please refresh the page to continue.\\n' => '\\nВаша сессия истекла или больше не действительна. Пожалуйста, обновите страницу, чтобы продолжить.\\n',
  '\\nYour account has been successfully activated. You can now log in and get started!\\n' => '\\nВаша учетная запись успешно активирована. Теперь вы можете войти в систему и начать!\\n',
  '\\nYou\'re all done\\n' => '\\nВсе готово\\n',
  '\\nEnter your email to reset your password\\n' => '\\nВведите адрес электронной почты, чтобы сбросить пароль\\n',
  '\\nIf your email is valid, a password reset link has been sent to your email address.\\n' => '\\nЕсли ваш адрес электронной почты действителен, на ваш адрес электронной почты была отправлена ссылка для сброса пароля.\\n',
  '\\nEnable%s\\n' => '\\nВключить%s\\n',
  '\\nAuto-Populate\\n' => '\\nАвтозаполнение\\n',
  '\\nAuto-populate from previously submitted forms\', \'en\']]' => '\\nАвтозаполнение из ранее отправленных форм\', \'ru\']]',
  '\\nEnable Auto-Populate to automatically populate this field\\n' => '\\nВключите автоматическое заполнение для автоматического заполнения этого поля\\n',
  '\\nAPI Auto-Populate Integration is Active\\n' => '\\nИнтеграция автоматического заполнения API активна\\n',
  '\\nThis form uses External API Auto-Populate. To configure settings, go to\\n' => '\\nЭта форма использует автоматическое заполнение внешнего API. Чтобы настроить параметры, перейдите по адресу\\n',
  '\\nAuto-Populate Integrations\\n' => '\\nАвтозаполнение интеграций\\n',
  '\\nSelect Form\\n' => '\\nВыберите форму\\n',
  '\\nTarget Form\\n' => '\\nЦелевая форма\\n',
  '\\nSelect a Form\\n' => '\\nВыберите форму\\n',
  '\\nSelect the form that will receive data from the API\\n' => '\\nВыберите форму, которая будет получать данные из API\\n',
  '\\nSearch Fields (Trigger Fields)\\n' => '\\nПоля поиска (поля триггера)\\n',
  '\\nPlease select a form first\\n' => '\\nСначала выберите форму\\n',
  '\\nTarget Fields (Fields to Fill)\\n' => '\\nЦелевые поля (поля для заполнения)\\n',
  '\\nMap API response fields to form fields. The API data will automatically fill these fields.\\n' => '\\nСопоставьте поля ответа API для формирования полей. Данные API автоматически заполнят эти поля.\\n',
  '\\nNo fillable fields found in this form\\n' => '\\nВ этой форме не найдено полей для заполнения\\n',
  '[[\'field\', \'en\']]' . chr(0) . '[[\'fields\', \'en\']]' => '[[\'поле\', \'эн\']]' . chr(0) . '[[\'поля\', \'ru\']]' . chr(0) . '[[\'поля\', \'ru\']]',
  '\\nAPI Field Name\\n' => '\\nИмя поля API\\n',
  '\\nForm Field\\n' => '\\nПоле формы\\n',
  '\\nSelect Field\\n' => '\\nВыберите поле\\n',
  '\\nCache Settings\\n' => '\\nНастройки кэша\\n',
  '\\nCache API responses to improve performance\\n' => '\\nКэшируйте ответы API для повышения производительности\\n',
  '\\nExternal API Connections\\n' => '\\nВнешние API-соединения\\n',
  '\\nAdd API Connection\\n' => '\\nДобавить соединение API\\n',
  '\\nUpload the%sfile\\n' => '\\nЗагрузите файл%s\\n',
  'CSV' => 'CSV-файл',
  '\\nDataset\\n' => '\\nНабор данных\\n',
  '[[\'The%shas been successfully completed\\n' => '[[\'%sуспешно завершен\\n',
  'Rename' => 'Переименовать',
  'Source' => 'Источник',
  '\\n%snot found\\n' => '\\n%sне найден\\n',
  '\\n%sLocation\\n' => '\\n%sМестоположение\\n',
  '\\ninstallation\\n' => '\\nустановка\\n',
  '\\nThe%shave been deleted.\\n' => '\\n%sудален.\\n',
  '\\nThe%sfield must be correctly filled out to proceed.\', \'en\']]' => '\\nДля продолжения поле%sдолжно быть правильно заполнено.\', \'ru\']]',
  '\\nSubmitted Form\\n' => '\\nОтправленная форма\\n',
  '\\nYou can\'t add reCAPTCHA to payment forms.\\n' => '\\nВы не можете добавить reCAPTCHA в формы оплаты.\\n',
  '\\nLearn more about%sor watch the video tutorial.\\n' => '\\nУзнайте больше о%sили посмотрите видеоруководство.\\n',
  '\\nLearn more%s\\n' => '\\nПодробнее%s\\n',
  '\\nGoogle reCAPTCHA\\n' => '\\nGoogle reCAPTCHA\\n',
  '\\nThe connection was interrupted, but don\\\'t worry—your edits are safely stored in your browser. Refresh the page to continue working.\\n' => '\\nСоединение было прервано, но не волнуйтесь: ваши изменения надежно хранятся в вашем браузере. Обновите страницу, чтобы продолжить работу.\\n',
  '[["There is an auto-saved version of the form available. Do you want to restore it?\\n' => '[["Доступна автоматически сохраняемая версия формы. Хотите восстановить ее?\\n',
  '\\nSMS notification could not be sent. Check if the SMS plugin is installed and configured properly.\\n' => '\\nНе удалось отправить SMS-уведомление. Проверьте, правильно ли установлен и настроен плагин SMS.\\n',
  '\\nYour request was completed successfully.%1$s%2$s\\n' => '\\nВаш запрос успешно выполнен.%1$s%2$s\\n',
  '\\nPayPal\\n' => '\\nPayPal\\n',
  '\\nTo use%1$sfeatures in your forms, you need to get your%2$skeys.\\n' => '\\nЧтобы использовать функции%1$sв своих формах, вам необходимо получить ключи%2$s.\\n',
  '\\nGo to the add-ons page in the Flux Forms plugin, install the%sadd-on, and try again.\\n' => '\\nПерейдите на страницу надстроек в плагине Flux Forms, установите надстройку%sи повторите попытку.\\n',
  '\\nTo create a payment form to collect online payments, install a payment add-on such as the%sAdd-on first.\\n' => '\\nЧтобы создать платежную форму для сбора онлайн-платежей, сначала установите надстройку для оплаты, например надстройку%s.\\n',
  'Activated' => 'Активировано',
  '\\nThank\\n' => '\\nСпасибо\\n',
  '\\nThe%splugin may interfere with Flux Forms form functionality. If you encounter any issues with the forms, disable caching for the Flux Forms plugin in the%ssettings.\\n' => '\\nПлагин%sможет мешать работе форм Flux Forms. Если у вас возникли проблемы с формами, отключите кеширование для плагина Flux Forms в настройках%s.\\n',
  '\\nRemind me later\\n' => '\\nНапомни мне позже\\n',
  '[["Got it, don\'t show it again\\n' => '[["Понятно, больше не показывать\\n',
  '\\nThe value of the%1$sfield does not match the pattern and must be at least%2$scharacters.\\n' => '\\nЗначение поля%1$sне соответствует шаблону и должно содержать не менее символов%2$s.\\n',
  '\\nThe value of the%1$sfield does not match the pattern and must be at most%2$scharacters.\\n' => '\\nЗначение поля%1$sне соответствует шаблону и должно содержать не более символов%2$s.\\n',
  '[[\'Please enter valid value for the%sfield.\\n' => '[[\'Пожалуйста, введите допустимое значение в поле%s.\\n',
  '\\n%slist\\n' => '\\n Список%s\\n',
  '\\nThe uploaded file exceeds the allowable limit of%sMB.\\n' => '\\nЗагруженный файл превышает допустимый лимит%sМБ.\\n',
  '\\nThe uploaded file is below the required minimum size of%sMB.\\n' => '\\nРазмер загруженного файла меньше требуемого минимального размера%sМБ.\\n',
  '\\nReview the entered values in the%stab. This message appeared because an error was detected.\\n' => '\\nПроверьте введенные значения на вкладке%s. Это сообщение появилось, потому что была обнаружена ошибка.\\n',
  '\\nAre you sure you want to duplicate the "%s" ?\\n' => '\\nВы уверены, что хотите дублировать «%s»?\\n',
