  '\\nOffline Forms\', \'en\']]' => '\\nОфлайн-формы\', \'ru\']]',
  '\\nPersia Payment\\n' => '\\nПерсидский платеж\\n',
  '\\nPersian Date Picker\\n' => '\\nПерсидский выбор даты\\n',
  '\\nArabic Date Picker\\n' => '\\nВыбор даты на арабском языке\\n',
  '\\nGoogle Sheets\\n' => '\\nGoogle Таблицы\\n',
  '\\nConditional Logic\\n' => '\\nУсловная логика\\n',
  '\\nYour subscription needs renewing before the missing add-ons can be restored.\\n' => '\\nВашу подписку необходимо продлить, прежде чем можно будет восстановить недостающие дополнения.\\n',
  '\\nThe missing add-on files could not be restored. Check the server connection and file permissions, then try again.\\n' => '\\nОтсутствующие файлы дополнения не удалось восстановить. Проверьте подключение к серверу и права доступа к файлу, затем повторите попытку.\\n',
  '\\nYou do not have permission to do this.\\n' => '\\nУ вас нет разрешения на это.\\n',
  '\\nAll required add-ons were restored.\\n' => '\\nВсе необходимые дополнения были восстановлены.\\n',
  '\\nFinish updating Flux Forms\\n' => '\\nЗавершить обновление форм Flux\\n',
  '\\nSome add-on files are missing\\n' => '\\nНекоторые дополнительные файлы отсутствуют\\n',
  '\\nThe plugin was updated, so its add-ons must be reinstalled before this page can load. Click the button below to install them.\\n' => '\\nПлагин был обновлен, поэтому его надстройки необходимо переустановить, прежде чем эта страница сможет загрузиться. Нажмите кнопку ниже, чтобы установить их.\\n',
  '\\nOne or more add-on files are missing. Click the button below to reinstall them.\\n' => '\\nОтсутствует один или несколько дополнительных файлов. Нажмите кнопку ниже, чтобы переустановить их.\\n',
  '\\nAutomatic recovery was attempted but did not finish. Review the reason below, fix it if necessary, then try again.\\n' => '\\nПопытка автоматического восстановления не завершилась. Просмотрите причину ниже, при необходимости устраните ее и повторите попытку.\\n',
  '\\nRecover add-ons\\n' => '\\nВосстановить дополнения\\n',
  '\\nInstalling add-ons...\\n' => '\\nУстановка дополнений...\\n',
  '\\nInstallation complete.\\n' => '\\nУстановка завершена.\\n',
  '\\nClick to activate the add-ons.\\n' => '\\nНажмите, чтобы активировать дополнения.\\n',
  '[[\'Activate add-ons\\n' => '[[\'Активировать дополнения\\n',
  '\\nInstallation failed. Please try again.\\n' => '\\nУстановка не удалась. Пожалуйста, попробуйте еще раз.\\n',
  '\\nMissing add-ons:\', \'en\']]' => '\\nОтсутствуют дополнения:\', \'ru\']]',
  '\\nWhy the recovery failed\\n' => '\\nПочему восстановление не удалось\\n',
  '\\nPreparing your form\\n' => '\\nПодготовка формы\\n',
  '\\nAdd-ons restored successfully\\n' => '\\nДополнения успешно восстановлены\\n',
  '\\nThe form is being prepared. This page will reload automatically.\\n' => '\\nФорма находится в стадии подготовки. Эта страница перезагрузится автоматически.\\n',
  '\\nThe page will reload automatically so the restored add-ons can be activated.\\n' => '\\nСтраница перезагрузится автоматически, чтобы можно было активировать восстановленные дополнения.\\n',
  '\\nReload now\\n' => '\\nПерезагрузить сейчас\\n',
  '\\nThis form is temporarily unavailable.\\n' => '\\nЭта форма временно недоступна.\\n',
  '\\nWe could not restore a required form component automatically. Please try again shortly; the site administrator can view the exact recovery error in Flux Forms.\\n' => '\\nНе удалось автоматически восстановить необходимый компонент формы. Пожалуйста, повторите попытку через некоторое время; администратор сайта может просмотреть точную ошибку восстановления в формах Flux.\\n',
  '\\nThe add-on is already installed.\\n' => '\\nДополнение уже установлено.\\n',
  '\\nFile access status not checked yet. Please wait.\\n' => '\\nСостояние доступа к файлу еще не проверено. Пожалуйста, подождите.\\n',
  '\\nError: server (%s) responded with an invalid request. responded code:%s\\n' => '\\nОшибка: сервер (%s) ответил неверным запросом. код ответа:%s\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the%sserver\\n' => '\\nНевозможно установить дополнения Flux Forms, поскольку плагин не может подключиться к серверу%s\\n',
  '\\nYour Easy Form Builder Pro subscription has expired, so the Pro add-ons could not be downloaded. The plugin keeps working without them. Renew your subscription to restore all Pro features:\\n' => '\\nСрок действия вашей подписки на Easy Form Builder Pro истек, поэтому дополнения Pro невозможно загрузить. Плагин продолжает работать и без них. Продлите подписку, чтобы восстановить все функции Pro:\\n',
  '\\nThe version of the add-on is not compatible with the version of the Flux Forms plugin.\\n' => '\\nВерсия дополнения несовместима с версией плагина Flux Forms.\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to download files\\n' => '\\nНевозможно установить дополнения Flux Forms, поскольку плагин не может загружать файлы\\n',
  '\\nCannot install add-ons because this server has disabled the PHP filesystem functions needed to prepare the download. Please ask your hosting provider to enable mkdir and rename, or configure the WordPress filesystem.\\n' => '\\nНевозможно установить дополнения, поскольку на этом сервере отключены функции файловой системы PHP, необходимые для подготовки загрузки. Попросите вашего хостинг-провайдера включить mkdir и переименовать или настроить файловую систему WordPress.\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to move the downloaded file\\n' => '\\nНевозможно установить дополнения Flux Forms, поскольку плагин не может переместить загруженный файл\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to unzip files\', \'en\']]' => '\\nНевозможно установить дополнения Flux Forms, поскольку плагин не может разархивировать файлы\', \'ru\']]',
  '\\nTo fix this, sign in to your%s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.\\n' => '\\nЧтобы это исправить, войдите в свою учетную запись%s, загрузите плагин Add-ons Handler из раздела «Загрузки», затем установите и активируйте его. После этого активируйте нужные вам надстройки с помощью плагина Add-ons Handler.\\n',
  '\\nWhiteStudio dashboard\\n' => '\\nПанель управления WhiteStudio\\n',
  '\\nThis bundled add-on is missing from the plugin files.\\n' => '\\nЭто дополнение отсутствует в файлах плагина.\\n',
  '\\nThe add-on server returned an unexpected response.\\n' => '\\nДополнительный сервер вернул неожиданный ответ.\\n',
  '\\nThe add-on could not be installed.\\n' => '\\nНе удалось установить дополнение.\\n',
  '\\nThe add-on server did not provide a download URL.\\n' => '\\nСервер дополнений не предоставил URL-адрес для загрузки.\\n',
  '\\nThe add-on download URL is not an approved Flux Forms source.\\n' => '\\nURL-адрес загрузки дополнения не является одобренным источником Flux Forms.\\n',
  '\\nYour server could not reach%1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at%2$sand download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.\\n' => '\\nВаш сервер не смог связаться с%1$s, поэтому дополнение не удалось загрузить. Почти всегда это брандмауэр на вашем хостинге, блокирующий исходящий запрос, а не проблема с вашей лицензией. Чтобы установить надстройки вообще без какой-либо загрузки, войдите в систему на%2$sи загрузите плагин Flux Forms Add-ons Handler, а затем установите его, как любой другой плагин. Он содержит все дополнения, на которые распространяется ваша лицензия.\\n',
  '\\nIf you would rather fix the connection, ask your hosting provider why outgoing requests from%sare being blocked.\\n' => '\\nЕсли вы предпочитаете исправить соединение, узнайте у своего хостинг-провайдера, почему блокируются исходящие запросы от%s.\\n',
  '\\nFlux Forms: add-on downloads are being blocked\\n' => '\\nFlux Forms: загрузка дополнений блокируется\\n',
  '\\nAdd-on affected:%s\\n' => '\\nЗатронуто дополнение:%s\\n',
  '\\nNo response was recorded for this add-on.\\n' => '\\nДля этого дополнения не было записано ни одного ответа.\\n',
  '\\nWritable\\n' => '\\nДоступно для записи\\n',
  '\\nNot writable — the add-on folder cannot be created or extracted into.\\n' => '\\nНедоступно для записи — папку дополнения невозможно создать или извлечь в нее.\\n',
  '\\nBlocked by WP_HTTP_BLOCK_EXTERNAL — outgoing requests are disabled on this site.\\n' => '\\nЗаблокировано WP_HTTP_BLOCK_EXTERNAL — на этом сайте отключены исходящие запросы.\\n',
  'Allowed' => 'Разрешено',
  '\\nDISABLE_WP_CRON is on — background retries only run if a server cron task calls wp-cron.php.\\n' => '\\nDISABLE_WP_CRON включен — фоновые повторные попытки выполняются только в том случае, если задача cron сервера вызывает wp-cron.php.\\n',
  'Site' => 'Сайт',
  '\\nPage that needed it\\n' => '\\nСтраница, которой это нужно\\n',
  '\\nPlugin version\\n' => '\\nВерсия плагина\\n',
  'WordPress' => 'WordPress',
  '\\nAdd-on folder\\n' => '\\nПапка дополнений\\n',
  '\\nOutgoing requests\\n' => '\\nИсходящие запросы\\n',
  '\\nWP-Cron\\n' => '\\nWP-Cron\\n',
  '\\nAttempts made\\n' => '\\nПопытки\\n',
  '\\nFlux Forms could not reinstall its add-on files automatically. Forms that rely on those add-ons are showing a temporary message to visitors until this is resolved.\\n' => '\\nFlux Forms не удалось автоматически переустановить дополнительные файлы. Формы, использующие эти надстройки, показывают посетителям временное сообщение, пока проблема не будет решена.\\n',
  '\\nWhat is missing\\n' => '\\nЧего не хватает\\n',
  '\\nDiagnostics\\n' => '\\nДиагностика\\n',
  '\\nWhat to do next\\n' => '\\nЧто делать дальше\\n',
  '\\nOpen Flux Forms in your dashboard and use the Recover add-ons button.\\n' => '\\nОткройте формы Flux на панели управления и используйте кнопку «Восстановить надстройки».\\n',
  '\\nIf the add-on folder is not writable, ask your host to allow writing to the plugin folder.\\n' => '\\nЕсли папка дополнения недоступна для записи, попросите вашего хостера разрешить запись в папку плагина.\\n',
  '\\nIf outgoing requests are blocked, ask your host to allow connections to the Flux Forms update server.\\n' => '\\nЕсли исходящие запросы заблокированы, попросите ваш хост разрешить подключения к серверу обновлений Flux Forms.\\n',
  '\\nIf your Pro subscription has expired, renew it to restore the Pro add-ons.\\n' => '\\nЕсли срок действия вашей подписки Pro истек, продлите ее, чтобы восстановить дополнения Pro.\\n',
  '\\nWe have made some updates. Please wait a few minutes before trying again.\\n' => '\\nМы внесли некоторые обновления. Пожалуйста, подождите несколько минут, прежде чем повторить попытку.\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the whitestudio.team server\\n' => '\\nНевозможно установить дополнения Flux Forms, поскольку плагин не может подключиться к серверу whitestudio.team\\n',
  '\\nOne of the free features\\n' => '\\nОдна из бесплатных функций\\n',
  '\\nImportant: Caching Plugin May Affect Flux Forms\\n' => '\\nВажно: плагин кэширования может повлиять на формы Flux\\n',
  '\\nThe following caching plugins are active on your site:\\n' => '\\nНа вашем сайте активны следующие плагины кеширования:\\n',
  '\\nPlugin Name\\n' => '\\nИмя плагина\\n',
  '\\nSlug\\n' => '\\nСлизень\\n',
  '\\nPlease note that these plugins may affect the functionality of Flux Forms.\\n' => '\\nОбратите внимание, что эти плагины могут повлиять на функциональность Flux Forms.\\n',
  '\\nIf you experience any issues, please exclude the page where your form is published from caching or disable these plugins. For detailed guidance on how to set up this exclusion, please refer to the documentation of the respective caching plugin.\\n' => '\\nЕсли у вас возникли какие-либо проблемы, исключите страницу, на которой опубликована ваша форма, из кэширования или отключите эти плагины. Подробные инструкции по настройке этого исключения можно найти в документации соответствующего плагина кэширования.\\n',
  '\\nSent by\\n' => '\\nОтправлено\\n',
  '\\nAction needed: Flux Forms Pro is paused on%s\\n' => '\\nТребуется действие: Flux Forms Pro приостановлен на%s\\n',
  '\\nFlux Forms could not confirm your Pro licence for%1$sdays in a row, so the Pro features on%2$sare paused for now.\\n' => '\\nFlux Forms не может подтвердить вашу лицензию Pro в течение%1$sдней подряд, поэтому функции Pro на%2$sна данный момент приостановлены.\\n',
  '\\nYour forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored — nothing was deleted.\\n' => '\\nВаши формы, записи и настройки не тронуты, все бесплатные функции продолжают работать, а ваш код активации по-прежнему сохраняется — ничего не было удалено.\\n',
  '\\nOpen%1$sYT Form → Settings%2$sand press%1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.\\n' => '\\nОткройте форму%1$sYT → Настройки%2$sи нажмите%1$sСохранить%2$s. Это немедленно проверяет лицензию еще раз; если соединение восстановится, Pro включится через минуту.\\n',
  '\\nStill paused? Ask your hosting provider to allow outgoing HTTPS connections to%s— a firewall, proxy or regional block is the usual cause — then repeat step 1.\\n' => '\\nВсе еще приостановлено? Попросите своего хостинг-провайдера разрешить исходящие HTTPS-соединения к%s(обычной причиной является брандмауэр, прокси-сервер или региональная блокировка), а затем повторите шаг 1.\\n',
  '\\nIf your subscription has expired, or you moved this website to a new domain,%1$srenew or re-activate your licence%2$sand paste the new code into Settings.\', \'en\']]' => '\\nЕсли срок вашей подписки истек или вы переместили этот веб-сайт в новый домен,%1$sпродлите или повторно активируйте лицензию%2$sи вставьте новый код в настройки.\', \'en\']]',
  'Reason' => 'Причина',
  '\\nFirst failed check\\n' => '\\nПервая неудачная проверка\\n',
  '\\ngrace period\\n' => '\\nльготный период\\n',
  '%s days' => '%sдней',
  '\\nActivation code\\n' => '\\nКод активации\\n',
  '\\nError code\\n' => '\\nКод ошибки\\n',
  '\\nHow to bring Pro back\\n' => '\\nКак вернуть Pro\\n',
  '\\nCheck my licence now\\n' => '\\nПроверьте мою лицензию сейчас\\n',
  '\\nStill stuck? Send the details above to%1$sour support team%2$sand we will take it from there.\\n' => '\\nВсе еще застрял? Отправьте приведенную выше информацию%1$sв нашу службу поддержки%2$s, и мы примем меры.\\n',
  '\\nThe licence server answered with an error and could not confirm your licence.\\n' => '\\nСервер лицензий ответил с ошибкой и не смог подтвердить вашу лицензию.\\n',
  '\\nYour website could not reach the licence server — almost always a network, firewall or DNS restriction on the hosting side.\\n' => '\\nВаш веб-сайт не может связаться с сервером лицензий — почти всегда из-за ограничений сети, брандмауэра или DNS на стороне хостинга.\\n',
  '\\nThe licence server’s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.\\n' => '\\nОтвет сервера лицензий пришел поврежденным, обычно из-за того, что плагин безопасности, прокси-сервер или CDN изменили его по пути.\\n',
  '\\nThe licence check could not be completed.\\n' => '\\nПроверку лицензии не удалось завершить.\\n',
  '[[\'Your activation code has expired!\\n' => '[[\'Срок действия вашего кода активации истек!\\n',
  '\\nYour Easy Form Builder Pro subscription has expired. To continue using the%sadd-on and all Pro features, please renew your subscription.\\n' => '\\nСрок действия вашей подписки на Easy Form Builder Pro истек. Чтобы продолжить использование дополнения%sи всех функций версии Pro, продлите подписку.\\n',
  '\\nRenew Subscription\\n' => '\\nОбновить подписку\\n',
  '\\nPro Version Required\\n' => '\\nТребуется Pro-версия\\n',
  '\\nThe%sadd-on is a Pro feature. Please upgrade to Flux Forms Pro to access this functionality.\\n' => '\\nДополнение%s— это функция Pro. Пожалуйста, обновите Flux Forms Pro, чтобы получить доступ к этой функции.\\n',
  '\\nYour Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running,%1$sRenew your subscription now.%2$s\\n' => '\\nСрок действия вашей подписки на Easy Form Builder Pro истек. Чтобы и дальше пользоваться всеми функциями версии Pro и поддерживать работоспособность форм,%1$sпродлите подписку прямо сейчас.%2$s\\n',
  '\\nThe payment could not be verified yet.\\n' => '\\nПлатеж пока не удалось подтвердить.\\n',
  '\\nThis payment provider does not support refunds from the site.\\n' => '\\nЭтот поставщик платежей не поддерживает возврат средств с сайта.\\n',
  'Completed' => 'Завершено',
  'Active' => 'Активный',
  '\\nTrial\\n' => '\\nПробная версия\\n',
  'Pending' => 'Ожидается',
  'Processing' => 'Обработка',
  '\\nCanceled\\n' => '\\nОтменено\\n',
  '\\nAmount mismatch\\n' => '\\nНесоответствие суммы\\n',
  'Past due' => 'Просроченный платеж',
  '\\nUnpaid\\n' => '\\nНеоплачиваемый\\n',
  '\\nIncomplete\\n' => '\\nНеполный\\n',
  '\\nExpired\\n' => '\\nСрок действия истек\\n',
  'Refunded' => 'Возвращено',
  'Partly refunded' => 'Частично возмещено',
  '\\nSorry, you are not allowed to access this page.\\n' => '\\nК сожалению, у вас нет доступа к этой странице.\\n',
  '\\nPayments taken through your forms, from every payment provider. API keys and the active provider are set on the plugin Settings page, Payment tab.\\n' => '\\nПлатежи, принимаемые через ваши формы от каждого поставщика платежей. Ключи API и активный провайдер задаются на странице настроек плагина, вкладка «Оплата».\\n',
  'Settings saved.' => 'Настройки сохранены.',
  '\\nA Stripe webhook signing secret starts with "whsec_".\\n' => '\\nСекрет подписи вебхука Stripe начинается с «whsec_».\\n',
  '\\nProviders and webhooks\\n' => '\\nПоставщики и веб-перехватчики\\n',
  '\\nConfigured\\n' => '\\nНастроено\\n',
  '\\nNot configured\', \'en\']]' => '\\nНе настроено\', \'ru\']]',
  '\\nWebhook URL for this provider (if it sends payment notifications):\\n' => '\\nURL вебхука для этого провайдера (если он отправляет уведомления о платежах):\\n',
  '\\nRecent payments\\n' => '\\nПоследние платежи\\n',
  '\\nNo payments yet.\\n' => '\\nПлатежей пока нет.\\n',
  '\\nConfirmation code\\n' => '\\nКод подтверждения\\n',
  'Provider' => 'Поставщик',
  'Type' => 'Тип',
  'Amount' => 'Сумма',
  'Status' => 'Статус',
  '\\nTransaction ID\\n' => '\\nИдентификатор транзакции\\n',
  '\\nSubscription\\n' => '\\nПодписка\\n',
  '[[\'One-time\\n' => '[[\'Одноразовый\\n',
  '\\nThe latest%dpayments are shown.\\n' => '\\nОтображаются последние платежи%d.\\n',
  '\\nTest provider (development only)\\n' => '\\nПоставщик тестов (только для разработки)\\n',
  '[[\'Test outcome\\n' => '[[\'Результат теста\\n',
  '\\nApprove every payment\\n' => '\\nПодтвердить каждый платеж\\n',
  '\\nDecline every payment\\n' => '\\nОтклонять каждый платеж\\n',
  '\\nNo money is taken. Development only.\\n' => '\\nДеньги не берутся. Только разработка.\\n',
  '\\nTEST MODE: no card is charged.\\n' => '\\nТЕСТОВЫЙ РЕЖИМ: оплата с карты не взимается.\\n',
  '\\nTest provider: the payment was declined.\\n' => '\\nПровайдер тестирования: платеж отклонен.\\n',
  '[[\'Publishable key\\n' => '[[\'Публикуемый ключ\\n',
  'Secret key' => 'Секретный ключ',
  '\\nStripe is not configured on this site. Please contact the site administrator.\\n' => '\\nStripe не настроен на этом сайте. Пожалуйста, свяжитесь с администратором сайта.\\n',
  '\\nThe payment method of this form is not supported.\\n' => '\\nСпособ оплаты, указанный в этой форме, не поддерживается.\\n',
  '\\nThe payment could not be started. Please try again.\\n' => '\\nНе удалось начать платеж. Пожалуйста, попробуйте еще раз.\\n',
  '\\nOptional but recommended: in the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated and customer.subscription.deleted, then paste its signing secret below.\\n' => '\\nНеобязательно, но рекомендуется: на панели управления Stripe добавьте конечную точку веб-перехватчика с этим URL-адресом и событиями pay_intent.succeeded, pay_intent.pay_failed, pay_intent.canceled, charge.refunded, customer.subscription.updated и customer.subscription.deleted, а затем вставьте секрет подписи ниже.\\n',
  '\\nWebhook signing secret\\n' => '\\nСекрет подписи вебхука\\n',
  '\\nSaved - leave empty to keep it\\n' => '\\nСохранено: оставьте пустым, чтобы сохранить его.\\n',
  '\\nRemove the saved secret\\n' => '\\nУдалить сохраненный секрет\\n',
  '\\nInvalid or expired nonce\\n' => '\\nНеверный или просроченный одноразовый номер\\n',
  '\\nNo payment provider is available on this site. Please contact the site administrator.\\n' => '\\nНа этом сайте нет платежных систем. Пожалуйста, свяжитесь с администратором сайта.\\n',
  '\\nToo many payment attempts. Please wait a few minutes and try again.\\n' => '\\nСлишком много попыток оплаты. Пожалуйста, подождите несколько минут и повторите попытку.\\n',
  '\\nInvalid payment data. Please refresh the page and try again.\\n' => '\\nНеверные данные платежа. Пожалуйста, обновите страницу и повторите попытку.\\n',
  '\\nThe payment provider is not configured on this site. Please contact the site administrator.\\n' => '\\nПоставщик платежей не настроен на этом сайте. Пожалуйста, свяжитесь с администратором сайта.\\n',
  '\\nNo payment amount detected. Please review your selected items and try again. If the problem persists, contact support.\\n' => '\\nСумма платежа не обнаружена. Пожалуйста, проверьте выбранные элементы и повторите попытку. Если проблема не устранена, обратитесь в службу поддержки.\\n',
  '\\nToo many requests. Please wait a moment and try again.\\n' => '\\nСлишком много запросов. Пожалуйста, подождите немного и повторите попытку.\\n',
  '\\nPayment not found.\\n' => '\\nПлатеж не найден.\\n',
  '\\nYour payment has not been confirmed yet. Please wait a moment and try again. If the problem persists, contact the site administrator.\\n' => '\\nВаш платеж еще не подтвержден. Пожалуйста, подождите немного и повторите попытку. Если проблема не устранена, обратитесь к администратору сайта.\\n',
  '\\nOnline payment is not available at the moment. Please try again later or contact us.\\n' => '\\nОнлайн-оплата в данный момент недоступна. Пожалуйста, повторите попытку позже или свяжитесь с нами.\\n',
  '\\nActive payment provider\\n' => '\\nАктивный поставщик платежей\\n',
  '\\nPayment forms take card payments through this provider. Only installed providers are listed.\\n' => '\\nПлатежные формы принимают платежи по картам через этого провайдера. В списке указаны только установленные поставщики.\\n',
  '\\nSaved — leave empty to keep\\n' => '\\nСохранено — оставьте пустым, чтобы сохранить\\n',
  '\\n%ssettings\\n' => '\\n Настройки%s\\n',
