  'Each line shows something the site needs and whether it is in place. Fix the errors first; warnings are worth a look.' => 'В каждой строке показано, что нужно сайту и есть ли это на месте. Сначала исправьте ошибки; предупреждения заслуживают внимания.',
  'OK' => 'ОК',
