  '\\nPayment hand-off\\n' => '\\nПередача платежа\\n',
  '\\nFlux Donate handles payments (providers, keys, webhooks): Donations › Payments.\\n' => '\\nFlux Donate обрабатывает платежи (провайдеры, ключи, вебхуки): Пожертвования › Платежи.\\n',
  '[[\'Flux Donate is active but did not take over payments (filter flxb_own_payments is off?). Flux Forms uses its own Stripe settings.\\n' => '[[\'Flux Donate активен, но не принимает платежи (фильтр flxb_own_pays отключен?). Flux Forms использует собственные настройки Stripe.\\n',
  '\\nFlux Donate is not active; Flux Forms takes payments itself with%s.\\n' => '\\nFlux Donate не активен; Flux Forms сам принимает платежи с помощью%s.\\n',
  '[[\'Flux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".\', \'en\']]' . chr(0) . '[[\'Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".\', \'en\']]' => '[[\'Flux Donate не активен и ключи Stripe отсутствуют: форма оплаты%dпоказывает «Онлайн-платеж недоступен».\', \'en\']]' . chr(0) . '[[\'Flux Donate не активен, а ключи Stripe отсутствуют: в формах оплаты%dотображается сообщение «Онлайн-платеж недоступен».\', \'en\']]' . chr(0) . '[[\'Flux Donate не активен, а ключи Stripe отсутствуют: в формах оплаты%dотображается сообщение «Онлайн-платеж недоступен».\', \'en\']]',
  '\\nFlux Donate is not active and no Stripe keys are set. No payment form exists, so nothing is affected.\\n' => '\\nFlux Donate не активен, и ключи Stripe не установлены. Форма оплаты не существует, поэтому это ни на что не повлияет.\\n',
  '\\nPanel › Settings › Payment\\n' => '\\nПанель › Настройки › Оплата\\n',
  '\\nNot active. Forms work; donations are not tracked and recurring iyzico payments are not available.\\n' => '\\nНе активно. Формы работают; пожертвования не отслеживаются, а регулярные платежи iyzico недоступны.\\n',
  '\\nFlux Certificates (automations)\\n' => '\\nСертификаты Flux (автоматизация)\\n',
  '\\nVersion%sis active; certificate automations can run.\\n' => '\\nВерсия%sактивна; автоматизация сертификатов может работать.\\n',
  '\\nVersion%1$sis active; certificate automations need%2$sor later.\\n' => '\\nВерсия%1$sактивна; для автоматизации сертификатов требуется%2$sили более поздняя версия.\\n',
  '[[\'Not active, but%dactive automation creates or sends certificates; it will fail.\', \'en\']]' . chr(0) . '[[\'Not active, but%dactive automations create or send certificates; they will fail.\', \'en\']]' => '[[\'Не активно, но%dактивная автоматизация создает или отправляет сертификаты; это потерпит неудачу.\', \'ru\']]' . chr(0) . '[[\'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.\', \'ru\']]' . chr(0) . '[[\'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.\', \'ru\']]',
  '\\nNot active. Needed only for certificate automations.\\n' => '\\nНе активно. Требуется только для автоматизации сертификатов.\\n',
  '\\nAutomations\\n' => '\\nАвтоматизация\\n',
  '\\nNo automation is on. After a form or payment nothing runs automatically (certificate, e-mail, webhook).\\n' => '\\nАвтоматизация не включена. После формы или платежа ничего не запускается автоматически (сертификат, электронная почта, вебхук).\\n',
  '[[\'%dautomation is on.\', \'en\']]' . chr(0) . '[[\'%dautomations are on.\', \'en\']]' => '[[\' Автоматизация%dвключена.\', \'en\']]' . chr(0) . '[[\' Автоматизация%dвключена.\', \'en\']]' . chr(0) . '[[\' Автоматизация%dвключена.\', \'en\']]',
  '[[\'%drun failed in the last 7 days; see the run log.\', \'en\']]' . chr(0) . '[[\'%druns failed in the last 7 days; see the run log.\', \'en\']]' => '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]' . chr(0) . '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]' . chr(0) . '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]',
  '\\nKeys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.\\n' => '\\nКлючи установлены; Форма%dиспользует reCAPTCHA. В формах%dиспользуется reCAPTCHA.\\n',
  '[[\'%dform has reCAPTCHA on but the site key or secret key is missing; the form is not shown.\', \'en\']]' . chr(0) . '[[\'%dforms have reCAPTCHA on but the site key or secret key is missing; they are not shown.\', \'en\']]' => '[[\' В форме%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; форма не отображается.\', \'ru\']]' . chr(0) . '[[\' В формах%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; они не показаны.\', \'ru\']]' . chr(0) . '[[\' В формах%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; они не показаны.\', \'ru\']]',
  '\\nUploads folder\\n' => '\\nПапка «Загрузки»\\n',
