  '\\nClear Logs\', \'en\']]' => '\\nОчистить журналы\', \'ru\']]',
  '\\nThe Security & Spam Protection admin data could not be loaded. Another plugin may be blocking the script settings, or the page was cached. Reload the page; if it persists, disable admin script optimization for this page.\\n' => '\\nНе удалось загрузить данные администратора безопасности и защиты от спама. Возможно, другой плагин блокирует настройки скрипта, или страница была закеширована. Перезагрузить страницу; если проблема не исчезнет, отключите оптимизацию сценариев администратора для этой страницы.\\n',
  '\\nThe Security & Spam Protection panel failed to render. Reload the page or check the browser console.\\n' => '\\nНе удалось отобразить панель «Безопасность и защита от спама». Перезагрузите страницу или проверьте консоль браузера.\\n',
  '\\nProtection is paused: required PHP functions are disabled on this server:%s. Ask your host to remove them from the disable_functions line in php.ini. Your forms keep working without protection until then.\\n' => '\\nЗащита приостановлена: на этом сервере отключены необходимые функции PHP:%s. Попросите вашего хостера удалить их из строки Disable_functions в php.ini. До этого момента ваши формы будут работать без защиты.\\n',
  '\\nProtection is paused: the add-on database tables could not be created. Check that the database user can CREATE tables, then reload this page.\\n' => '\\nЗащита приостановлена: не удалось создать дополнительные таблицы базы данных. Убедитесь, что пользователь базы данных может СОЗДАТЬ таблицы, а затем перезагрузите эту страницу.\\n',
  '\\nProtection is paused: the WordPress REST API is not available on this site.\\n' => '\\nЗащита приостановлена: WordPress REST API недоступен на этом сайте.\\n',
  '\\nBehavior scoring\\n' => '\\nОценка поведения\\n',
