  '\\nChallenge TTL seconds\\n' => '\\nИспытание TTL секунд\\n',
  '[[\'How long a browser challenge can stay open.\\n' => '[[\'Как долго браузерный вызов может оставаться открытым.\\n',
  '\\nAll API requests per IP/min\\n' => '\\nВсе запросы API по IP/мин\\n',
  '\\nGlobal application-layer backstop.\\n' => '\\nГлобальная защита на уровне приложений.\\n',
