  '\\nUpload the CSV file using the upload button.\\n' => '\\nЗагрузите CSV-файл с помощью кнопки загрузки.\\n',
  '\\nUpload Dataset\\n' => '\\nЗагрузить набор данных\\n',
  '\\nIn Form Builder, open Form Settings and enable "Auto-Populate". Choose your dataset, then map elements to dataset fields as search conditions.\', \'en\']]' => '\\nВ Конструкторе форм откройте «Настройки формы» и включите «Автозаполнение». Выберите набор данных, затем сопоставьте элементы с полями набора данных в качестве условий поиска.\', \'ru\']]',
  '\\nEnable Auto-Populate\\n' => '\\nВключить автоматическое заполнение\\n',
  '[[\'For each target field, enable "Auto-Populate to automatically populate this field" and select the dataset column to auto-populate.\\n' => '[[\'Для каждого целевого поля включите «Автозаполнение для автоматического заполнения этого поля» и выберите столбец набора данных для автоматического заполнения.\\n',
  '\\nMap Fields\\n' => '\\nПоля карты\\n',
  '\\nYou can edit dataset values inline by clicking on them.\\n' => '\\nВы можете редактировать значения набора данных в режиме реального времени, нажимая на них.\\n',
  '\\nFollow these steps to set up auto-populate for your forms\\n' => '\\nВыполните следующие действия, чтобы настроить автоматическое заполнение форм.\\n',
  '\\nQuick Start Guide\\n' => '\\nКраткое руководство\\n',
  '\\nTips & Notes\\n' => '\\nСоветы и примечания\\n',
  '\\nEditing Data\\n' => '\\nРедактирование данных\\n',
  '\\nSupported format: CSV with UTF-8 encoding.\\n' => '\\nПоддерживаемый формат: CSV с кодировкой UTF-8.\\n',
  '\\nForm Builder Tips\\n' => '\\nСоветы по созданию форм\\n',
  '[[\'Use conditions to filter dataset rows based on user input.\\n' => '[[\'Используйте условия для фильтрации строк набора данных на основе пользовательского ввода.\\n',
  '\\nMultiple fields can auto-populate from the same dataset.\\n' => '\\nНесколько полей могут автоматически заполняться из одного и того же набора данных.\\n',
  'Good to know' => 'Приятно знать',
  '\\nChanges to the dataset take effect immediately for new form submissions.\\n' => '\\nИзменения в наборе данных вступают в силу немедленно для новых отправок форм.\\n',
  '\\nConnect & Manage API Integrations\\n' => '\\nПодключение и управление интеграцией API\\n',
  '\\nReal-time Data\\n' => '\\nДанные в реальном времени\\n',
  '\\nField Mapping\\n' => '\\nСопоставление полей\\n',
