  '\\nTotal Connections\\n' => '\\nВсего подключений\\n',
  'Connections' => 'Соединения',
  '\\nAPI connections configured\\n' => '\\nAPI-соединения настроены\\n',
  '\\nHow to use API Integrations\\n' => '\\nКак использовать интеграцию API\\n',
  '\\nFollow these steps to connect your external API\\n' => '\\nВыполните следующие действия, чтобы подключить внешний API\\n',
  '\\nClick "Add API Connection" to create a new connection and enter your API endpoint URL.\\n' => '\\nНажмите «Добавить соединение API», чтобы создать новое соединение, и введите URL-адрес конечной точки API.\\n',
  '\\nAdd Connection\\n' => '\\nДобавить соединение\\n',
  '\\nConfigure authentication (API Key, Bearer Token, or Basic Auth) if your API requires it.\\n' => '\\nНастройте аутентификацию (ключ API, токен носителя или базовую аутентификацию), если этого требует ваш API.\\n',
  'Authentication' => 'Аутентификация',
  '\\nSelect a form and map API response fields to your form fields for auto-populate.\\n' => '\\nВыберите форму и сопоставьте поля ответа API с полями формы для автоматического заполнения.\\n',
  '\\nUse the Test button to verify the API returns expected data, then save your connection.\\n' => '\\nИспользуйте кнопку «Тест», чтобы убедиться, что API возвращает ожидаемые данные, затем сохраните соединение.\\n',
  '\\nTest & Save\\n' => '\\nПроверить и сохранить\\n',
  '\\nUse cache settings to reduce API calls and improve performance.\', \'en\']]' => '\\nИспользуйте настройки кэша, чтобы уменьшить количество вызовов API и повысить производительность.\', \'ru\']]',
  'Performance' => 'Производительность',
  '\\nSet a reasonable timeout to prevent slow form loading.\\n' => '\\nУстановите разумное время ожидания, чтобы предотвратить медленную загрузку формы.\\n',
  '\\nAlways use HTTPS endpoints for secure data transfer.\\n' => '\\nВсегда используйте конечные точки HTTPS для безопасной передачи данных.\\n',
  '\\nKeep API keys confidential — they are stored securely in WordPress.\', \'tr\']]' => '\\nСохраняйте конфиденциальность ключей API — они надежно хранятся в WordPress.\', \'tr\']]',
  '\\nAPI responses are fetched in real-time when the form loads. Enable caching for frequently accessed data.\\n' => '\\nОтветы API извлекаются в режиме реального времени при загрузке формы. Включите кэширование для часто используемых данных.\\n',
