  'Rule name' => 'Название правила',
  'Priority' => 'Приоритет',
  'All of these are true (AND)' => 'Все это правда (И)',
  'Any of these is true (OR)' => 'Любое из этих утверждений верно (ИЛИ)',
  'Add group' => 'Добавить группу',
  'Add action' => 'Добавить действие',
