  'Block submission' => 'Заблокировать отправку',
  'Conditional logic rules updated. Save the form to keep them.' => 'Обновлены правила условной логики. Сохраните форму, чтобы сохранить их.',
  'Incomplete conditions or actions were removed.' => 'Неполные условия или действия были удалены.',
  'A rule hides or shows a field it also reads. That field can never become visible again once hidden.' => 'Правило скрывает или показывает поле, которое оно также читает. Это поле никогда больше не станет видимым после того, как оно будет скрыто.',
  '(deleted field)' => '(удалено поле)',
  'This form does not accept Stripe payments.' => 'Эта форма не принимает платежи Stripe.',
  'This form does not accept online payments.' => 'Эта форма не принимает онлайн-платежи.',
  '[[\'The currency of this form is not supported.\\n' => '[[\'Валюта этой формы не поддерживается.\\n',
  'The payment amount is too large.' => 'Сумма платежа слишком велика.',
  'Your payment has not been confirmed by Stripe yet. Please wait a moment and try again. If the problem persists, contact the site administrator.' => 'Ваш платеж еще не подтвержден Stripe. Пожалуйста, подождите немного и повторите попытку. Если проблема сохраняется, обратитесь к администратору сайта.',
  'Stripe Payments' => 'Полосовые платежи',
  'The publishable and secret API keys are set on the plugin Settings page, Payment tab.' => 'Публикуемые и секретные ключи API задаются на странице настроек плагина, вкладка «Оплата».',
