  '\\nfield\\x00fields\\n' => '[[\'поле\', \'эн\']]' . chr(0) . '[[\'поля\', \'ru\']]' . chr(0) . '[[\'поля\', \'ru\']]',
  '\\nFlux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".\\x00Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".\\n' => '[[\'Flux Donate не активен и ключи Stripe отсутствуют: форма оплаты%dпоказывает «Онлайн-платеж недоступен».\', \'en\']]' . chr(0) . '[[\'Flux Donate не активен, а ключи Stripe отсутствуют: в формах оплаты%dотображается сообщение «Онлайн-платеж недоступен».\', \'en\']]' . chr(0) . '[[\'Flux Donate не активен, а ключи Stripe отсутствуют: в формах оплаты%dотображается сообщение «Онлайн-платеж недоступен».\', \'en\']]',
  '\\nNot active, but%dactive automation creates or sends certificates; it will fail.\\x00Not active, but%dactive automations create or send certificates; they will fail.\\n' => '[[\'Не активно, но%dактивная автоматизация создает или отправляет сертификаты; это потерпит неудачу.\', \'ru\']]' . chr(0) . '[[\'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.\', \'ru\']]' . chr(0) . '[[\'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.\', \'ru\']]',
  '[[\'%dautomation is on.\\x00%dautomations are on.\\n' => '[[\' Автоматизация%dвключена.\', \'en\']]' . chr(0) . '[[\' Автоматизация%dвключена.\', \'en\']]' . chr(0) . '[[\' Автоматизация%dвключена.\', \'en\']]',
  '\\n%drun failed in the last 7 days; see the run log.\\x00%druns failed in the last 7 days; see the run log.\\n' => '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]' . chr(0) . '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]' . chr(0) . '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]',
  '\\n%dform has reCAPTCHA on but the site key or secret key is missing; the form is not shown.\\x00%dforms have reCAPTCHA on but the site key or secret key is missing; they are not shown.\\n' => '[[\' В форме%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; форма не отображается.\', \'ru\']]' . chr(0) . '[[\' В формах%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; они не показаны.\', \'ru\']]' . chr(0) . '[[\' В формах%dвключена reCAPTCHA, но отсутствует ключ сайта или секретный ключ; они не показаны.\', \'ru\']]',
  '\\nForm\\x00Forms\\n' => '[[\'Форма\', \'эн\']]' . chr(0) . '[[\'Формы\', \'ru\']]' . chr(0) . '[[\'Формы\', \'ru\']]',
  '[[\'%dservice account connected\\x00%dservice accounts connected\\n' => '[[\'Учетная запись службы%dподключена\', \'en\']]' . chr(0) . '[[\' Подключены сервисные учетные записи%d\', \'en\']]' . chr(0) . '[[\' Подключены сервисные учетные записи%d\', \'en\']]',
  '\\n%dcolumn will be written to the sheet.\\x00%dcolumns will be written to the sheet.\\n' => '[[\' Столбец%dбудет записан на лист.\', \'en\']]' . chr(0) . '[[\' Столбцы%dбудут записаны на лист.\', \'en\']]' . chr(0) . '[[\' Столбцы%dбудут записаны на лист.\', \'en\']]',
  '\\nRemove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.\\x00Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.\\n' => '[[\'Удалить привязку ALL%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.\', \'ru\']]' . chr(0) . '[[\'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.\', \'ru\']]' . chr(0) . '[[\'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.\', \'ru\']]',
  '\\nYou can attach up to%1$dfile here. Please wait about%2$dminutes before trying again.\\x00You can attach up to%1$dfiles here. Please wait about%2$dminutes before trying again.\\n' => '[[\'Здесь вы можете прикрепить файл%1$d. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.\', \'ru\']]' . chr(0) . '[[\'Здесь вы можете прикрепить до%1$dфайлов. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.\', \'ru\']]' . chr(0) . '[[\'Здесь вы можете прикрепить до%1$dфайлов. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.\', \'ru\']]',
