  '\\nNot active, but%dactive automation creates or sends certificates; it will fail.\\x00Not active, but%dactive automations create or send certificates; they will fail.\\n' . chr(0) . '\\nNot active, but%dactive automation creates or sends certificates; it will fail.\\x00Not active, but%dactive automations create or send certificates; they will fail.\\n' => '[[\'Не активно, но%dактивная автоматизация создает или отправляет сертификаты; это потерпит неудачу.\', \'ru\']]' . chr(0) . '[[\'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.\', \'ru\']]' . chr(0) . '[[\'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.\', \'ru\']]',
  '[[\'%dautomation is on.\\x00%dautomations are on.\\n' . chr(0) . '[[\'%dautomation is on.\\x00%dautomations are on.\\n' => '[[\' Автоматизация%dвключена.\', \'en\']]' . chr(0) . '[[\' Автоматизация%dвключена.\', \'en\']]' . chr(0) . '[[\' Автоматизация%dвключена.\', \'en\']]',
  '\\n%drun failed in the last 7 days; see the run log.\\x00%druns failed in the last 7 days; see the run log.\\n' . chr(0) . '\\n%drun failed in the last 7 days; see the run log.\\x00%druns failed in the last 7 days; see the run log.\\n' => '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]' . chr(0) . '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]' . chr(0) . '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]',
