  'Your Pro activation code will be removed from this site. Pro add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.' => '\\nВаш код активации Pro будет удален с этого сайта. Дополнения Pro будут недоступны, пока вы не обновите их снова. Ваши формы, записи и настройки не будут удалены.\\n',
  'Switch to Free?' => '\\nПерейти на бесплатную версию?\\n',
  'Advanced features and advanced fields used in your forms will be disabled. Your forms, entries and settings will not be deleted, and will be available again if you upgrade.' => '\\nРасширенные функции и дополнительные поля, используемые в ваших формах, будут отключены. Ваши формы, записи и настройки не будут удалены и снова станут доступны после обновления.\\n',
  'Your Pro activation code will be removed from this site. Advanced features, Pro fields and add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.' => '\\nВаш код активации Pro будет удален с этого сайта. Расширенные функции, поля Pro и надстройки будут недоступны, пока вы не обновитесь снова. Ваши формы, записи и настройки не будут удалены.\\n',
