  'Your registration is successful.' => '\\nВаша регистрация прошла успешно.\\n',
  'You have successfully subscribed. Thank you!' => '\\nВы успешно подписались. Спасибо!\\n',
  'Thank You for taking the time to complete this survey.' => '\\nСпасибо, что нашли время заполнить этот опрос.\\n',
  'Please go to Panel > Settings > Email Settings, click "Check Email Server", then click "Save".' => '\\nПерейдите в Панель > Настройки > Настройки электронной почты, нажмите «Проверить сервер электронной почты», затем нажмите «Сохранить».\\n',
  'Uh oh, looks like there is a problem with the form. Please make sure all of the input is correct.' => '\\nОй, похоже, проблема с формой. Пожалуйста, убедитесь, что все введенные данные верны.\\n',
  'The form was not created' => '\\nФорма не была создана\\n',
  'Scripts tags are not allowed.' => '\\nТеги сценариев не разрешены.\\n',
  'Bootstrap Template' => '\\nШаблон начальной загрузки\\n',
  'Warning: If your theme uses Bootstrap, make sure the option below is enabled.' => '\\nВнимание: если ваша тема использует Bootstrap, убедитесь, что опция ниже включена.\\n',
  'My theme is based on Bootstrap' => '\\nМоя тема основана на Bootstrap\\n',
  'Uh oh, it looks like there is a problem with your request. Please review everything and try again.' => '\\nОй, похоже, с вашим запросом возникла проблема. Пожалуйста, просмотрите все и повторите попытку.\\n',
  'Please type in your message' => '\\nПожалуйста, введите ваше сообщение\', \'ru\']]',
  'The files have been deleted.' => '\\nФайлы были удалены.\\n',
  'The activation code you entered is incorrect. Please double-check and try again.' => '\\nВведенный вами код активации неверен. Пожалуйста, проверьте еще раз и повторите попытку.\\n',
  'We are sorry, but the message was not sent due to a settings error. Please contact the admin for assistance.' => '\\nПриносим извинения, но сообщение не было отправлено из-за ошибки в настройках. Пожалуйста, обратитесь к администратору за помощью.\\n',
  'OR' => '\\nИЛИ\\n',
  'Email Template' => '\\nШаблон электронной почты\\n',
  'reset' => '\\nсброс\\n',
  'Not Found' => '\\nНе найден\\n',
  'Editor' => '\\nРедактор\\n',
  'Please add the shortcode_message shortcode to the email template.' => '\\nПожалуйста, добавьте короткий код shortcode_message в шаблон электронного письма.\\n',
  'Your Email Template cannot exceed 10,000 characters.' => '\\nВаш шаблон электронной почты не может превышать 10 000 символов.\\n',
  'Please use HTML tags to create your email template.' => '\\nДля создания шаблона электронной почты используйте HTML-теги.\\n',
  'Add this shortcode inside a tag to display the title of the email.' => '\\nДобавьте этот короткий код в тег, чтобы отобразить заголовок электронного письма.\\n',
  'Add this shortcode inside an HTML tag to display the message content of an email.' => '\\nДобавьте этот короткий код в тег HTML, чтобы отобразить содержимое сообщения электронной почты.\\n',
  'To display the website name, add this shortcode inside an HTML tag.' => '\\nЧтобы отобразить название веб-сайта, добавьте этот короткий код в HTML-тег.\\n',
  'Add this shortcode within an HTML tag to display the Website URL.' => '\\nДобавьте этот короткий код в тег HTML, чтобы отобразить URL-адрес веб-сайта.\\n',
  'You can display the Admin Email address of your WordPress site by adding this shortcode within an HTML tag.' => '\\nВы можете отобразить адрес электронной почты администратора вашего сайта WordPress, добавив этот короткий код в HTML-тег.\\n',
  'Max selection' => '\\nМаксимальный выбор\\n',
