  'Your cart is currently empty. Please add items to continue.' => '\\nВаша корзина в настоящее время пуста. Пожалуйста, добавьте элементы, чтобы продолжить.\\n',
  'Payment Multi choose' => '\\nВыбор нескольких вариантов оплаты\\n',
