  'XXSmall' => '\\nXXМаленький\\n',
  'Create a payment form to collect online payments.' => '\\nСоздайте платежную форму для сбора онлайн-платежей.\\n',
  'Submit' => '\\nОтправить\\n',
  'Purchase Order' => '\\nЗаказ на покупку\\n',
  'It is not possible to include reCAPTCHA on payment forms.' => '\\nНевозможно включить reCAPTCHA в формы оплаты.\\n',
  'This site can send emails' => '\\nЭтот сайт может отправлять электронные письма\\n',
  'Weekly email health and form activity report' => '\\nЕженедельный отчет о состоянии электронной почты и активности форм\\n',
  'Adds your form activity totals &ndash; forms, views and submissions &ndash; to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => '\\nДобавляет общие сведения о вашей активности в форме (формы, просмотры и отправки) в еженедельное электронное письмо, которое ваш сайт отправляет главному администратору. Эти итоговые данные считываются на вашем сайте и никогда не отправляются в WhiteStudio.\\n',
  'No automated email check has run yet.' => '\\nАвтоматическая проверка электронной почты пока не выполнялась.\\n',
  'Collect email delivery statistics' => '\\nСбор статистики доставки электронной почты\\n',
  'Counts how many emails were sent or failed, shows them in the dashboard widget, and adds the email delivery status section to the weekly email. Once a week your site runs a delivery test and reports the result. Only Pro users can turn this off.' => '\\nПодсчитывает, сколько писем было отправлено или не отправлено, показывает их в виджете информационной панели и добавляет раздел статуса доставки электронной почты в еженедельное электронное письмо. Раз в неделю ваш сайт проводит тест доставки и сообщает о результате. Только пользователи Pro могут отключить это.\\n',
  'Interval' => '\\nИнтервал\\n',
  'Next Billing Date' => '[[\'Следующая дата выставления счета\\n',
  'Yearly' => '\\nЕжегодно\\n',
  'How to activate the Pro version of Flux Forms' => '\\nКак активировать Pro-версию Flux Forms\\n',
  'Uploaded File' => '\\nЗагруженный файл\\n',
  'Your internet connection has been lost, but do not worry, we have saved the information you entered on this form. Once you are reconnected to the internet, you can easily send your information by clicking the submit button.' => '\\nВаше подключение к Интернету прервано, но не волнуйтесь: мы сохранили информацию, которую вы ввели в эту форму. После повторного подключения к Интернету вы сможете легко отправить свою информацию, нажав кнопку «Отправить».\\n',
  'Please ensure that you have a stable internet connection and try again.' => '\\nУбедитесь, что у вас стабильное подключение к Интернету, и повторите попытку.\\n',
  'There was a problem uploading the file and the form was not submitted. Please check that your internet connection is stable and try again.' => '\\nПри загрузке файла возникла проблема, и форма не была отправлена. Пожалуйста, проверьте стабильность вашего интернет-соединения и повторите попытку.\\n',
  'You are experiencing issues with jQuery. Please contact the administrator for assistance. (Error code: JQ-500)' => '\\nУ вас возникли проблемы с jQuery. Обратитесь за помощью к администратору. (Код ошибки: JQ-500)\\n',
  'Your session has expired. Please refresh the page and try again.' => '\\nВаш сеанс истек. Пожалуйста, обновите страницу и повторите попытку.\\n',
  'Basic' => '\\nБазовый\\n',
  'Sign-In|Up' => '\\nВойти|Вверх\\n',
  'Advance' => '\\nДополнительно\\n',
  'Thank you Page' => '\\nСтраница благодарности\\n',
  'Redirect page' => '\\nПеренаправление страницы\\n',
  'Please wait, you will be redirected shortly.' => '\\nПожалуйста, подождите, вы будете перенаправлены в ближайшее время.\\n',
  'Persia payment' => '\\nПерсидский платеж\\n',
  'Unlock Pro Features Today' => '[[\'Разблокируйте функции Pro сегодня\\n',
  'Upgrade to Pro for just %1$s%2$s%3$s/year and get access to powerful features, including advanced form fields, payment integrations, conditional logic, multi-step forms, file uploads, Security & Spam Protection, and priority support.%4$sView Pro Features%5$s' => '\\nОбновите версию Pro всего за%1$s%2$s%3$sв год и получите доступ к мощным функциям, включая расширенные поля форм, интеграцию платежей, условную логику, многошаговые формы, загрузку файлов, безопасность и защиту от спама, а также приоритетную поддержку.%4$sВозможности View Pro%5$s\\n',
  'Add-on' => '\\nДополнение\\n',
  'Add-ons' => '\\nДополнения\\n',
  'Stripe Payment Add-on' => '[[\'Дополнение Stripe Payment\\n',
  'The Stripe add-on for Flux Forms enables you to integrate your WordPress site with Stripe for payment processing, donations, and online orders.' => '\\nДополнение Stripe для Flux Forms позволяет интегрировать ваш сайт WordPress с Stripe для обработки платежей, пожертвований и онлайн-заказов.\\n',
  'Offline Forms Add-on' => '[[\'Дополнение к автономным формам\\n',
  'The Offline Forms add-on for Flux Forms allows users to save their progress when filling out forms in offline situations.' => '\\nДополнение «Офлайн-формы» для Flux Forms позволяет пользователям сохранять прогресс при заполнении форм в автономном режиме.\\n',
  'Please update Flux Forms before trying again.' => '[["Пожалуйста, обновите Flux Forms, прежде чем повторить попытку.\\n',
  'Activation of offline form mode.' => '\\nАктивация режима офлайн-формы.\\n',
  'Before activating this option, install' => '\\nПеред активацией этой опции установите\\n',
  'To create a payment form to collect online payments, you must first install a payment add-on such as the Stripe Add-on.' => '\\nЧтобы создать платежную форму для сбора онлайн-платежей, необходимо сначала установить платежную надстройку, например надстройку Stripe.\\n',
  'All formats' => '\\nВсе форматы\\n',
  'EFB SMS Add-on' => '\\nДополнение EFB SMS\\n',
  'Enable SMS functionality in your forms with the EFB SMS add-on, allowing you to validate mobile numbers and send confirmation codes via SMS, as well as receive notifications through SMS service.' => '\\nВключите функцию SMS в своих формах с помощью надстройки EFB SMS, которая позволит вам проверять номера мобильных телефонов и отправлять коды подтверждения через SMS, а также получать уведомления через службу SMS.\\n',
  'Advanced confirmation code Add-on' => '\\nДополнительный код подтверждения\\n',
  'Send a confirmation code via email or SMS to users and/or admins, allowing them to quickly access new responses.' => '\\nОтправьте код подтверждения по электронной почте или SMS пользователям и/или администраторам, чтобы они могли быстро получить доступ к новым ответам.\\n',
  'Box Checklist' => '\\nКонтрольный список коробки\\n',
  'Radio Checklist' => '\\nКонтрольный список радио\\n',
  'This is a warning for WPBakery users. For more information, please click here.' => '\\nЭто предупреждение для пользователей WPBakery. Для получения дополнительной информации нажмите здесь.\\n',
  'Are you sure you want to close replies to this message?' => '\\nВы уверены, что хотите закрыть ответы на это сообщение?\\n',
  'Are you sure you want to open the responses to this message?' => '\\nВы уверены, что хотите открыть ответы на это сообщение?\\n',
  'The response has been closed by Admin.' => '\\nОтвет закрыт администратором.\\n',
  'The response has been opened by Admin.' => '\\nОтвет открыт администратором.\\n',
  '$NN/year' => '\\n$NN/год\\n',
  'columns' => '\\nстолбцы\\n',
  'column' => '\\nстолбец\\n',
  'I would like to localize Flux Forms.' => '\\nЯ хотел бы локализовать Flux Forms.\\n',
  'Max length' => '\\nМакс. длина\\n',
  'Min length' => '\\nМинимальная длина\\n',
  'The maximum number of characters allowed in the input element is 524288' => '\\nМаксимальное количество символов, допустимое во входном элементе, — 524288\\n',
  'Please enter a value that is at least NN characters long.' => '\\nПожалуйста, введите значение длиной не менее NN символов.\\n',
  'Please enter a number that is greater than or equal to NN.' => '\\nПожалуйста, введите число, большее или равное NN.\\n',
  'Please Enter a maximum of NN Characters For this field' => '\\nВведите в это поле максимум NN символов\\n',
  'Please enter a number that is less than or equal to NN' => '\\nПожалуйста, введите число, меньшее или равное NN\\n',
  'Max' => '\\nМакс\\n',
  'Min' => '\\nМин\\n',
  'Minimum entry must be lower than the maximum entry' => '\\nМинимальная запись должна быть ниже максимальной.\\n',
  'Hide the label' => '\\nСкрыть ярлык\\n',
  'Hide label on mobile' => '\\nСкрыть ярлык на мобильном устройстве\\n',
  'Hide description on mobile' => '\\nСкрыть описание на мобильном устройстве\\n',
  'Hide all labels on mobile' => '\\nСкрыть все ярлыки на мобильном устройстве\\n',
  'Click here for more details' => '\\nНажмите здесь, чтобы получить более подробную информацию\\n',
  'Label of the ON status' => '\\nЯрлык состояния включения\\n',
  'Label of the OFF status' => '\\nЯрлык состояния ВЫКЛ.\\n',
  '5 Point Scale' => '\\n5-балльная шкала\\n',
  'Net Promoter Score' => '\\nЧистая оценка промоушена\\n',
  'NPS Table Matrix' => '\\nМатрица таблицы NPS\\n',
  'Jalali Date' => '\\nДата Джалали\\n',
  'Hijri Date' => '\\nДата хиджры\\n',
  'Install the add-on' => '\\nУстановите дополнение\\n',
  'Please go to the Add-ons Page of Flux Forms plugin and install the Jalili date addons' => '\\nПерейдите на страницу дополнений плагина Flux Forms и установите дополнения к дате Jalili.\\n',
  'Please go to the Add-ons Page of Flux Forms plugin and install the Hijri date addons' => '\\nПерейдите на страницу дополнений плагина Flux Forms и установите дополнения к дате Хиджры.\\n',
  'date & time' => '\\nдата и время\\n',
  'Enable file upload in the response box' => '\\nВключить загрузку файлов в поле ответа\\n',
  'Enable Google reCAPTCHA in the response box' => '\\nВключите Google reCAPTCHA в поле ответа\\n',
  'Enable download button in the response box' => '\\nВключить кнопку загрузки в поле ответа\\n',
  'Display the IP addresses of users in the response box.' => '\\nОтображение IP-адресов пользователей в поле ответа.\\n',
  'Persia Payment Add-on' => '\\nПлатежное дополнение Persia\\n',
  'The Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.' => '\\nПлатежный модуль Persia для Flux Forms позволяет вам подключить свой веб-сайт к платежной системе Persia для обработки платежей, пожертвований и онлайн-заказов.\\n',
  'Jalali Date Add-on' => '\\nДополнение «Джалали»\\n',
  'The Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.' => '\\nДополнение «Дата Джалали» позволяет вам добавлять поле даты Джалали в ваши формы и создавать формы любого типа, включающие это поле даты Шамси.\\n',
  'Hijri Date Add-on' => '\\nДополнение к дате Хиджры\\n',
  'The Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.' => '\\nДополнение «Дата Хиджры» позволяет добавлять поле даты Хиджры в ваши формы и создавать формы любого типа, включающие это поле.\\n',
  'SMS service Add-on' => '\\nДополнение к SMS-сервису\\n',
  'The SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.' => '\\nДополнение службы SMS позволяет вам получать SMS-уведомления, когда вы или ваши клиенты получаете новые сообщения или ответы.\\n',
  'Please install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.' => '\\nУстановите дополнение к дате Хиджры или Джалали. Вы не можете установить оба дополнения одновременно.\\n',
  'Response box' => '\\nПоле ответа\\n',
  'Regions Drop-Down' => '\\nРаскрывающийся список «Регионы»\\n',
  'You are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.' => '\\nВы видите это сообщение, потому что устанавливаются необходимые дополнения. Пожалуйста, подождите несколько минут, а затем посетите эту страницу еще раз. Если прошло более пяти минут и ничего не произошло, обратитесь в службу поддержки Flux Forms на сайте Whitestudio.team.\\n',
  'The cell phone number is incorrect' => '\\nНомер мобильного телефона указан неверно\\n',
  'Invalid country code' => '\\nНеверный код страны\\n',
  'The cell phone number is too short' => '\\nНомер мобильного телефона слишком короткий\\n',
  'The cell phone number is too long' => '\\nНомер мобильного телефона слишком длинный\\n',
  'Please select the number of countries to display within an acceptable range.' => '\\nПожалуйста, выберите количество стран для отображения в пределах допустимого диапазона.\\n',
  'Disabled Field' => '\\nОтключенное поле\\n',
  'Hidden Field' => '\\nСкрытое поле\\n',
  'Select a country to display a list of states/provinces.' => '[[\'Выберите страну для отображения списка штатов/провинций.\\n',
  'Select a state/province to display a list of cities.' => '\\nВыберите штат/провинцию, чтобы отобразить список городов.\\n',
  'SMS Service Add-on' => '\\nДополнительная служба SMS\\n',
  'This field is currently unavailable. Please contact the site administrator.' => '[["Это поле в настоящее время недоступно. Пожалуйста, свяжитесь с администратором сайта.\\n',
  'Would you like to customize the form using the colors of the active template?' => '\\nХотите настроить форму, используя цвета активного шаблона?\\n',
