  'The Conditional Logic module failed to load. Please refresh the page; if the problem continues, deactivate and reactivate the Conditional Logic add-on.' => '\\nНе удалось загрузить модуль условной логики. Пожалуйста, обновите страницу; если проблема не исчезнет, деактивируйте и повторно активируйте надстройку «Условная логика».\\n',
