  'Use email-safe HTML only. No script tags.' => '\\nИспользуйте только HTML, безопасный для электронной почты. Нет тегов скриптов.\\n',
  'blocks' => '\\nблоки\\n',
  'Copy shortcode' => '\\nСкопировать короткий код\\n',
