  'Response ID' => '\\nИдентификатор ответа\\n',
  'Payment hand-off' => '\\nПередача платежа\\n',
  'Flux Donate handles payments (providers, keys, webhooks): Donations › Payments.' => '\\nFlux Donate обрабатывает платежи (провайдеры, ключи, вебхуки): Пожертвования › Платежи.\\n',
  'Flux Donate is active but did not take over payments (filter flxb_own_payments is off?). Flux Forms uses its own Stripe settings.' => '[[\'Flux Donate активен, но не принимает платежи (фильтр flxb_own_pays отключен?). Flux Forms использует собственные настройки Stripe.\\n',
  'Flux Donate is not active; Flux Forms takes payments itself with %s.' => '\\nFlux Donate не активен; Flux Forms сам принимает платежи с помощью%s.\\n',
