  'Flux Donate is not active and no Stripe keys are set. No payment form exists, so nothing is affected.' => '\\nFlux Donate не активен, и ключи Stripe не установлены. Форма оплаты не существует, поэтому это ни на что не повлияет.\\n',
  'Panel › Settings › Payment' => '\\nПанель › Настройки › Оплата\\n',
  'Not active. Forms work; donations are not tracked and recurring iyzico payments are not available.' => '\\nНе активно. Формы работают; пожертвования не отслеживаются, а регулярные платежи iyzico недоступны.\\n',
  'Flux Certificates (automations)' => '\\nСертификаты Flux (автоматизация)\\n',
  'Version %s is active; certificate automations can run.' => '\\nВерсия%sактивна; автоматизация сертификатов может работать.\\n',
  'Version %1$s is active; certificate automations need %2$s or later.' => '\\nВерсия%1$sактивна; для автоматизации сертификатов требуется%2$sили более поздняя версия.\\n',
  'Not active, but %d active automation creates or sends certificates; it will fail.' . chr(0) . 'Not active, but %d active automations create or send certificates; they will fail.' => '[[\'Не активно, но%dактивная автоматизация создает или отправляет сертификаты; это потерпит неудачу.\', \'ru\']]' . chr(0) . '[[\'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.\', \'ru\']]' . chr(0) . '[[\'Не активно, но активные средства автоматизации%dсоздают или отправляют сертификаты; они потерпят неудачу.\', \'ru\']]',
  'Not active. Needed only for certificate automations.' => '\\nНе активно. Требуется только для автоматизации сертификатов.\\n',
  'Automations' => '\\nАвтоматизация\\n',
  'No automation is on. After a form or payment nothing runs automatically (certificate, e-mail, webhook).' => '\\nАвтоматизация не включена. После формы или платежа ничего не запускается автоматически (сертификат, электронная почта, вебхук).\\n',
  '%d automation is on.' . chr(0) . '%d automations are on.' => '[[\' Автоматизация%dвключена.\', \'en\']]' . chr(0) . '[[\' Автоматизация%dвключена.\', \'en\']]' . chr(0) . '[[\' Автоматизация%dвключена.\', \'en\']]',
  '%d run failed in the last 7 days; see the run log.' . chr(0) . '%d runs failed in the last 7 days; see the run log.' => '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]' . chr(0) . '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]' . chr(0) . '[[\' За последние 7 дней не удалось выполнить%d; см. журнал запусков.\', \'en\']]',
  'Keys are set; %d form uses reCAPTCHA.' . chr(0) . 'Keys are set; %d forms use reCAPTCHA.' => '\\nКлючи установлены; Форма%dиспользует reCAPTCHA. В формах%dиспользуется reCAPTCHA.\\n',
