  'Fix system requirements before protection can run.' => '\\nИсправьте системные требования перед запуском защиты.\\n',
  'Behavior checks and rate limits are running.' => '\\nПроверки поведения и ограничения скорости выполняются.\\n',
  'Quarantined' => '\\nНа карантине\\n',
  'Cost Suppressed' => '\\nСтоимость снижена\\n',
