  'Per-IP submit limit.' => '\\nОграничение отправки по IP.\\n',
  'Submits per IP/hour' => '\\nОтправок по IP/час\\n',
  'Longer per-IP submit limit.' => '\\nУвеличен лимит отправки для каждого IP.\\n',
  'Form global/min' => '\\nФорма глобальная/мин\\n',
  'Total submit pressure per form.' => '[[\'Общее давление отправки на форму.\\n',
  'Tracking lookups per IP/min' => '\\nОтслеживание запросов по IP/мин\\n',
  'Protects confirmation-code lookup.' => '\\nЗащищает поиск кода подтверждения.\\n',
  'Responses per IP/min' => '\\nОтветов на IP/мин\\n',
  'Protects public reply box.' => '\\nЗащищает поле общедоступных ответов.\\n',
  'Replies per tracking code/hour' => '\\nКоличество ответов на код отслеживания в час\\n',
  'Caps replies to one tracked conversation (across IPs). 0 disables.' => '\\nCaps отвечает на один отслеживаемый разговор (по IP-адресам). 0 отключает.\\n',
  'Uploads per IP/min' => '\\nКоличество загрузок на IP/мин\\n',
  'Protects upload endpoint.' => '\\nЗащищает конечную точку загрузки.\\n',
