  'Protects payment REST routes.' => '\\nЗащищает платежные маршруты REST.\\n',
  'File upload budget' => '\\nБюджет загрузки файлов\\n',
  'Flux Forms already limits uploads on its own: each visitor may upload three files per file field on the form, and the response box allows three. Leave a box at 0 to keep that automatic behaviour, or enter a number to set it yourself.' => '\\nFlux Forms уже ограничивает загрузку самостоятельно: каждый посетитель может загрузить три файла на одно поле формы в форме, а поле ответа позволяет три. Оставьте в поле 0, чтобы сохранить автоматическое поведение, или введите число, чтобы настроить его самостоятельно.\\n',
  'Uploads allowed per file field' => '\\nЗагрузки разрешены для каждого поля файла\\n',
  'Default 3, so a two-field form allows six uploads. 0 keeps the default.' => '\\nПо умолчанию 3, поэтому форма с двумя полями допускает шесть загрузок. 0 сохраняет значение по умолчанию.\\n',
  'Total uploads per visitor' => '\\nОбщее количество загрузок на посетителя\\n',
  'A fixed total that ignores how many fields the form has. 0 keeps the automatic per-field calculation.' => '\\nФиксированная сумма, которая игнорирует количество полей в форме. 0 сохраняет автоматический расчет для каждого поля.\\n',
  'Budget resets after (seconds)' => '\\nБюджет сбрасывается через (секунды)\\n',
  'Default 3600 (one hour). 0 keeps the default.' => '\\nПо умолчанию 3600 (один час). 0 сохраняет значение по умолчанию.\\n',
  'Maximum file size (MB)' => '\\nМаксимальный размер файла (МБ)\\n',
  'A site-wide ceiling. It can only tighten a per-field limit, never widen it. 0 keeps the field setting.' => '\\nПотолок по всему объекту. Он может только ужесточить ограничение на каждое поле, но никогда не расширять его. 0 сохраняет настройку поля.\\n',
  'Protect response lookup' => '\\nЗащитить поиск ответа\\n',
  'Rate-limit tracking-code searches by request count (no human-token check).' => '\\nОграничение скорости поиска кода отслеживания по количеству запросов (без проверки человеческого токена).\\n',
  'Manual access lists' => '\\nСписки ручного доступа\\n',
  'One entry per line: an exact IP or a wildcard prefix such as 203.0.113.* — allowlist bypasses all checks, blocklist blocks in every mode.' => '\\nОдна запись в строке: точный IP-адрес или префикс подстановочного знака, например 203.0.113.* — список разрешенных обходит все проверки, список блокировок блокируется в каждом режиме.\\n',
  'IP allowlist' => '[[\'Список разрешенных IP-адресов\\n',
  'Trusted IPs that skip the shield completely (your office, monitoring bots).' => '\\nДоверенные IP-адреса, которые полностью игнорируют защиту (ваш офис, мониторинг ботов).\\n',
  'IP blocklist' => '\\nЧерный список IP-адресов\\n',
  'IPs that are always blocked on protected form routes.' => '\\nIP-адреса, которые всегда блокируются на маршрутах защищенной формы.\\n',
  'Minimum paid notification score' => '\\nМинимальный балл платных уведомлений\\n',
  'Suppress costly notifications below this score.' => '\\nПодавить дорогостоящие уведомления ниже этого значения.\\n',
  'SMS daily stop-loss' => '[["Дневной стоп-лосс по SMS\\n',
  'Global SMS budget per day, across all recipients.' => '\\nГлобальный дневной бюджет SMS для всех получателей.\\n',
  'Telegram daily stop-loss' => '\\nДневной стоп-лосс в Telegram\\n',
  'Global Telegram budget per day, across all recipients.' => '\\nГлобальный дневной бюджет Telegram для всех получателей.\\n',
  'Webhook/Email daily stop-loss' => '\\nWebhook/ежедневный стоп-лосс по электронной почте\\n',
  'Global webhook/email/sheet budget per day.' => '\\nГлобальный дневной бюджет веб-перехватчика/электронной почты/таблицы.\\n',
  'Per-recipient daily cap' => '\\nДневное ограничение на каждого получателя\\n',
  'Maximum notifications per single recipient per day (0 disables).' => '\\nМаксимальное количество уведомлений на одного получателя в день (0 — отключить).\\n',
  'These limits become active for paid services after the core integration filter is added.' => '\\nЭти ограничения становятся активными для платных услуг после добавления основного фильтра интеграции.\\n',
  'Decisions — last 24 hours' => '\\nРешения — за последние 24 часа\\n',
  'Stacked per hour: allowed, blocked, quarantined and monitored requests.' => '\\nСкладывается в час: разрешенные, заблокированные, помещенные в карантин и отслеживаемые запросы.\\n',
  'No decisions recorded in the last 24 hours.' => '\\nЗа последние 24 часа решений не зарегистрировано.\\n',
  'Security logs' => '\\nЖурналы безопасности\\n',
  'Recent decisions without storing raw IP addresses.' => '\\nНедавние решения без хранения необработанных IP-адресов.\\n',
  'Clear Human Shield logs?' => '\\nОчистить журналы «Человеческого щита»?\\n',
  'Logs cleared.' => '[[\'Журналы очищены.\\n',
  'Latest security decisions.' => '\\nПоследние решения по безопасности.\\n',
  'No logs yet.' => '\\nЖурналов пока нет.\\n',
  'Route' => '\\nМаршрут\\n',
  'Score' => '[[\'Оценка\\n',
  'Reasons' => '\\nПричины\\n',
  'System readiness' => '\\nГотовность системы\\n',
  'Human Shield checks these functions before enforcing security rules.' => '\\nHuman Shield проверяет эти функции перед применением правил безопасности.\\n',
  'PHP requirements are ready.' => '\\nТребования PHP готовы.\\n',
