  'ready' => '\\nготов\\n',
  'not ready yet' => '\\nеще не готов\\n',
  'Recommended only after you verify PHP functions and tables are ready.' => '\\nРекомендуется только после проверки готовности функций и таблиц PHP.\\n',
  'Trust proxy IP headers' => '\\nДоверительные IP-заголовки прокси-сервера\\n',
  'Use forwarding headers only when the immediate peer matches the trusted proxy list below.' => '\\nИспользуйте заголовки пересылки только в том случае, если непосредственный узел соответствует приведенному ниже списку доверенных прокси.\\n',
  'Trusted proxy IPs' => '\\nДоверенные IP-адреса прокси\\n',
  'One exact IP or wildcard prefix per line. Add only your load balancer/CDN egress addresses; keep this empty when the origin is directly reachable.' => '\\nОдин точный IP-адрес или префикс подстановочного знака в каждой строке. Добавьте только исходящие адреса балансировщика нагрузки/CDN; оставьте это поле пустым, если источник доступен напрямую.\\n',
  'Store raw behavior metrics' => '\\nСохранение необработанных показателей поведения\\n',
  'Keep off for privacy unless debugging a rollout.' => '\\nНе отключайте в целях конфиденциальности, пока не отладите развертывание.\\n',
  'Log retention days' => '\\nДни хранения журналов\\n',
  'How long events should be retained.' => '\\nКак долго следует хранить события.\\n',
  'Client attestation timeout' => '\\nТайм-аут аттестации клиента\\n',
  'Milliseconds before the browser falls back to the normal request.' => '\\nМиллисекунды, прежде чем браузер вернется к обычному запросу.\\n',
  'If a required PHP function is disabled, enable it in php.ini disable_functions or ask the host to allow it. Cache and security plugins must not cache or rewrite POST responses from /wp-json/EmsfbShield/v1/*.' => '\\nЕсли необходимая функция PHP отключена, включите ее в php.inidisable_functions или попросите хост разрешить ее. Плагины кэша и безопасности не должны кэшировать или перезаписывать ответы POST из /wp-json/EmsfbShield/v1/*.\\n',
  'Security & Spam Protection tabs' => '\\nВкладки «Безопасность и защита от спама»\\n',
  'Security log export is unavailable because this server has disabled a required PHP function: %s. Ask your hosting provider to enable it.' => '\\nЭкспорт журнала безопасности недоступен, поскольку на этом сервере отключена необходимая функция PHP:%s. Попросите вашего хостинг-провайдера включить эту функцию.\\n',
  'Security log export is unavailable because this server has disabled required PHP functions: %s. Ask your hosting provider to enable them.' => '\\nЭкспорт журнала безопасности недоступен, поскольку на этом сервере отключены необходимые функции PHP:%s. Попросите вашего хостинг-провайдера включить их.\\n',
  'Auto-Populate Dataset' => '\\nАвтозаполнение набора данных\\n',
  'Manage & Upload Datasets' => '\\nУправление и загрузка наборов данных\\n',
