  'Easy Edit' => '\\nПростое редактирование\\n',
  'Total Datasets' => '\\nВсего наборов данных\\n',
  'Datasets' => '\\nНаборы данных\\n',
  'Datasets available for auto-populate' => '\\nНаборы данных доступны для автоматического заполнения\\n',
  'No datasets yet. Upload a CSV file to get started.' => '\\nНаборов данных пока нет. Чтобы начать, загрузите CSV-файл.\\n',
  'How to use Auto-Populate Datasets' => '\\nКак использовать автоматическое заполнение наборов данных\\n',
