  'Prepare CSV' => '[[\'Подготовить CSV\\n',
  'Upload the CSV file using the upload button.' => '\\nЗагрузите CSV-файл с помощью кнопки загрузки.\\n',
  'Upload Dataset' => '\\nЗагрузить набор данных\\n',
  'In Form Builder, open Form Settings and enable "Auto-Populate". Choose your dataset, then map elements to dataset fields as search conditions.' => '\\nВ Конструкторе форм откройте «Настройки формы» и включите «Автозаполнение». Выберите набор данных, затем сопоставьте элементы с полями набора данных в качестве условий поиска.\', \'ru\']]',
  'Enable Auto-Populate' => '\\nВключить автоматическое заполнение\\n',
  'For each target field, enable "Auto-Populate to automatically populate this field" and select the dataset column to auto-populate.' => '[[\'Для каждого целевого поля включите «Автозаполнение для автоматического заполнения этого поля» и выберите столбец набора данных для автоматического заполнения.\\n',
  'Map Fields' => '\\nПоля карты\\n',
  'You can edit dataset values inline by clicking on them.' => '\\nВы можете редактировать значения набора данных в режиме реального времени, нажимая на них.\\n',
  'Follow these steps to set up auto-populate for your forms' => '\\nВыполните следующие действия, чтобы настроить автоматическое заполнение форм.\\n',
  'Quick Start Guide' => '\\nКраткое руководство\\n',
  'Tips & Notes' => '\\nСоветы и примечания\\n',
  'Editing Data' => '\\nРедактирование данных\\n',
  'Supported format: CSV with UTF-8 encoding.' => '\\nПоддерживаемый формат: CSV с кодировкой UTF-8.\\n',
  'Form Builder Tips' => '\\nСоветы по созданию форм\\n',
  'Use conditions to filter dataset rows based on user input.' => '[[\'Используйте условия для фильтрации строк набора данных на основе пользовательского ввода.\\n',
  'Multiple fields can auto-populate from the same dataset.' => '\\nНесколько полей могут автоматически заполняться из одного и того же набора данных.\\n',
  'Changes to the dataset take effect immediately for new form submissions.' => '\\nИзменения в наборе данных вступают в силу немедленно для новых отправок форм.\\n',
  'Connect & Manage API Integrations' => '\\nПодключение и управление интеграцией API\\n',
  'Real-time Data' => '\\nДанные в реальном времени\\n',
  'Field Mapping' => '\\nСопоставление полей\\n',
  'Smart Cache' => '\\nУмный кэш\\n',
  'Total Connections' => '\\nВсего подключений\\n',
  'API connections configured' => '\\nAPI-соединения настроены\\n',
  'How to use API Integrations' => '\\nКак использовать интеграцию API\\n',
  'Follow these steps to connect your external API' => '\\nВыполните следующие действия, чтобы подключить внешний API\\n',
  'Click "Add API Connection" to create a new connection and enter your API endpoint URL.' => '\\nНажмите «Добавить соединение API», чтобы создать новое соединение, и введите URL-адрес конечной точки API.\\n',
  'Add Connection' => '\\nДобавить соединение\\n',
  'Configure authentication (API Key, Bearer Token, or Basic Auth) if your API requires it.' => '\\nНастройте аутентификацию (ключ API, токен носителя или базовую аутентификацию), если этого требует ваш API.\\n',
  'Select a form and map API response fields to your form fields for auto-populate.' => '\\nВыберите форму и сопоставьте поля ответа API с полями формы для автоматического заполнения.\\n',
  'Use the Test button to verify the API returns expected data, then save your connection.' => '\\nИспользуйте кнопку «Тест», чтобы убедиться, что API возвращает ожидаемые данные, затем сохраните соединение.\\n',
  'Test & Save' => '\\nПроверить и сохранить\\n',
  'Use cache settings to reduce API calls and improve performance.' => '\\nИспользуйте настройки кэша, чтобы уменьшить количество вызовов API и повысить производительность.\', \'ru\']]',
  'Set a reasonable timeout to prevent slow form loading.' => '\\nУстановите разумное время ожидания, чтобы предотвратить медленную загрузку формы.\\n',
  'Always use HTTPS endpoints for secure data transfer.' => '\\nВсегда используйте конечные точки HTTPS для безопасной передачи данных.\\n',
  'Keep API keys confidential — they are stored securely in WordPress.' => '\\nСохраняйте конфиденциальность ключей API — они надежно хранятся в WordPress.\', \'tr\']]',
  'API responses are fetched in real-time when the form loads. Enable caching for frequently accessed data.' => '\\nОтветы API извлекаются в режиме реального времени при загрузке формы. Включите кэширование для часто используемых данных.\\n',
