  'Google Sheet' => '\\nGoogle Таблица\\n',
  'Sync Form Responses to Google Sheets' => '\\nСинхронизировать ответы форм с Google Таблицами\\n',
  'Automatically send form submissions to your Google Sheets. Connect one or more service accounts, link a sheet to each form, and let data flow in real time — no webhook or browser login required.' => '\\nАвтоматически отправляйте отправленные формы в Google Таблицы. Подключите одну или несколько учетных записей служб, свяжите лист с каждой формой и позвольте данным передаваться в режиме реального времени — не требуется веб-перехватчик или вход в браузер.\\n',
  'Not Connected' => '\\nНе подключен\\n',
  'Auto Sync' => '\\nАвтосинхронизация\\n',
  'Auto Header' => '\\nАвто заголовок\\n',
  'Sync Logs' => '\\nЖурналы синхронизации\\n',
  'Google Sheet Settings' => '\\nНастройки Google Таблицы\\n',
  'Active Bindings' => '\\nАктивные привязки\\n',
  'Form' . chr(0) . 'Forms' => '[[\'Форма\', \'эн\']]' . chr(0) . '[[\'Формы\', \'ru\']]' . chr(0) . '[[\'Формы\', \'ru\']]',
  '%d service account connected' . chr(0) . '%d service accounts connected' => '[[\'Учетная запись службы%dподключена\', \'en\']]' . chr(0) . '[[\' Подключены сервисные учетные записи%d\', \'en\']]' . chr(0) . '[[\' Подключены сервисные учетные записи%d\', \'en\']]',
  'No service account connected yet' => '\\nСлужебный аккаунт пока не подключен\\n',
  'Form Bindings' => '\\nПривязки формы\\n',
  'Help & Guide' => '\\nПомощь и руководство\\n',
  'Saved successfully.' => '\\nСохранено успешно.\\n',
  'Open in Google Sheets' => '\\nОткрыть в Google Таблицах\\n',
  'Service Accounts' => '\\nСлужебные аккаунты\\n',
  'Connect one or more Google service accounts — no browser login required' => '\\nПодключите один или несколько аккаунтов сервисов Google — вход в браузер не требуется\\n',
  'Your server is missing the PHP OpenSSL extension.' => '\\nНа вашем сервере отсутствует расширение PHP OpenSSL.\\n',
  'Google Sheet sync cannot work until it is enabled. Please ask your host to enable the %s PHP extension, then reload this page.' => '\\nСинхронизация Google Sheet не может работать, пока она не включена. Попросите вашего хостера включить расширение PHP%s, а затем перезагрузите эту страницу.\\n',
  'Copy this email' => '\\nСкопируйте это письмо\\n',
  'Copy email' => '\\nКопировать письмо\\n',
  'To sync an <strong>existing</strong> sheet: open it in Google Sheets &rarr; <strong>Share</strong> &rarr; paste the email above &rarr; set role to <strong>Editor</strong>. To create a <strong>new</strong> sheet, just use Form Bindings — no sharing needed.' => '\\nЧтобы синхронизировать существующий лист<strong></strong>: откройте его в Google Sheets →<strong>Поделиться</strong>→ вставьте адрес электронной почты выше → установите роль<strong>Editor</strong>. Чтобы создать новый лист<strong></strong>, просто используйте привязки форм — общий доступ не требуется.\\n',
  'Set Default' => '\\nУстановить по умолчанию\\n',
  'Retest' => '\\nПовторное тестирование\\n',
  'Let’s connect Google Sheets — about 3 minutes, one time' => '\\nДавайте подключим Google Таблицы — примерно 3 минуты, один раз», «ru»]]',
  'Follow the numbered steps on the right to download a free service account key from Google, then drop the file below. You only do this once. After that, creating a sheet for any form is a couple of clicks.' => '\\nВыполните пронумерованные шаги справа, чтобы загрузить бесплатный ключ сервисной учетной записи от Google, а затем перетащите файл ниже. Вы делаете это только один раз. После этого создание листа для любой формы — это пара кликов.\\n',
  'Your Google email' => '\\nВаш адрес электронной почты Google\\n',
  '(recommended)' => '\\n(рекомендуется)\\n',
  'Any sheet the plugin <strong>creates</strong> is automatically shared to this address, so it appears in your own Google Drive under “Shared with me.” Without it, new sheets stay hidden inside the service account.' => '\\nЛюбой лист, который плагин<strong>создает</strong>, автоматически передается по этому адресу, поэтому он появляется на вашем Google Диске в разделе «Доступно мне». Без этого новые листы останутся скрытыми внутри учетной записи службы.\\n',
  'Enable Google Sheet Integration' => '\\nВключить интеграцию с Google Таблицами\\n',
  'Sync form submissions to your spreadsheets automatically' => '\\nАвтоматическая синхронизация отправленных форм с вашими таблицами\\n',
  'Drag & drop service account JSON file(s) here' => '\\nПеретащите сюда файлы JSON сервисного аккаунта\\n',
  'or click to browse — you can add multiple service accounts at once' => '\\или не нажимайте для просмотра — вы можете добавить несколько сервисных аккаунтов одновременно\\n',
  'Connected service accounts' => '\\nПодключенные сервисные аккаунты\\n',
  'One-time setup (≈3 min)' => '\\nОднократная установка (≈3 минуты)\\n',
  'Go to <a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a> &rarr; Project dropdown (top-left) &rarr; New Project &rarr; name it &rarr; Create' => '\\nПерейдите на<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ раскрывающийся список «Проект» (вверху слева) → «Новый проект» → назовите его → «Создать».\\n',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> <em>and</em> <strong>Google Drive API</strong>' => '\\nAPI и службы → Библиотека → включить<strong>Google Sheets API</strong><em>и</em><strong>Google Drive API</strong>\\n',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; name it &rarr; Done' => '\\nAPI и службы → Учетные данные → Создать учетные данные → Учетная запись службы → назовите ее → Готово\\n',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; JSON (downloads automatically)' => '\\nОткройте сервисный аккаунт → вкладка «Ключи» → «Добавить ключ» → «Создать новый ключ» → JSON (загружается автоматически)\\n',
  'Drag that downloaded file into the box on the left — it is tested automatically' => '\\nПеретащите загруженный файл в поле слева — он проверяется автоматически\\n',
  'Add <strong>Your Google email</strong> above so created sheets land in your Drive' => '\\nДобавьте<strong>свой адрес электронной почты Google</strong>, указанный выше, чтобы созданные листы попадали на ваш Диск.\\n',
  'Please choose a valid .json key file.' => '\\nПожалуйста, выберите действительный файл ключей .json.\\n',
  'Could not read file: %s' => '\\nНе удалось прочитать файл:%s\\n',
  'Connecting service account…' => '\\nПодключение сервисного аккаунта...\\n',
  'Service account added.' => '\\nСлужебный аккаунт добавлен.\\n',
  'Saved. New sheets created by the plugin will be shared to %s automatically.' => '\\nСохранено. Новые листы, созданные плагином, будут автоматически доступны%s.\\n',
  'Email cleared. New sheets will stay inside the service account until you share them.' => '\\nЭлектронная почта удалена. Новые листы останутся в сервисном аккаунте, пока вы не поделитесь ими.\\n',
  'Remove this service account?' => '\\nУдалить эту учетную запись службы?\\n',
  'Testing connection…' => '\\nПроверка соединения...\\n',
  'Connect each form to a specific Google Sheet tab' => '\\nПодключите каждую форму к определенной вкладке Google Sheet\\n',
  'Connect each form to a specific Google Sheet tab — step by step' => '\\nПодключите каждую форму к определенной вкладке Google Sheet — шаг за шагом\\n',
  'No service account connected.' => '\\nНет подключенной учетной записи службы.\\n',
  'Go to the Connections tab and drop a service account JSON key first.' => '\\nПерейдите на вкладку «Подключения» и сначала перетащите ключ JSON сервисного аккаунта.\\n',
  'Last sync OK' => '\\nПоследняя синхронизация ОК\\n',
  'Last sync failed' => '\\nПоследняя синхронизация не удалась\\n',
  'Remove sync? The sheet stays safe.' => '\\nУдалить синхронизацию? Лист останется в безопасности.\\n',
  'Yes, remove' => '\\nДа, удалить\\n',
  'Remove this sync (your Google Sheet is not deleted)' => '\\nУдалите эту синхронизацию (ваша таблица Google не будет удалена)\\n',
  'Existing Bindings' => '\\nСуществующие привязки\\n',
  'Delete All' => '\\nУдалить все\\n',
  'New Binding' => '\\nНовая привязка\\n',
