  'Tab' => '\\ntab\\n',
  'Choose Sheet' => '\\nВыберите лист\\n',
  'Columns & Fields' => '\\nСтолбцы и поля\\n',
  'Style & Save' => '\\nСтиль и сохранение\\n',
  'Which form should send data to Google Sheets?' => '\\nКакая форма должна отправлять данные в Google Таблицы?\\n',
  'Please select a form first.' => '\\nСначала выберите форму.\\n',
  'Service Account' => '\\nСлужебный аккаунт\\n',
  'Loading your spreadsheets…' => '\\nЗагрузка таблиц...\\n',
  'Click <strong>“Browse My Sheets”</strong> to list spreadsheets this service account can already access, or <strong>“Create New Sheet”</strong> to make a fresh one.' => '\\nНажмите<strong>«Просмотреть мои таблицы»</strong>, чтобы просмотреть таблицы, к которым уже имеет доступ этот сервисный аккаунт, или<strong>«Создать новый лист»</strong>, чтобы создать новую.\\n',
  '<strong>No spreadsheets are accessible to this service account yet.</strong> You have two options:' => '\\n<strong>Для этого сервисного аккаунта пока недоступны электронные таблицы.</strong>У вас есть два варианта:\\n',
  '<strong>Easiest:</strong> click <em>“Create New Sheet”</em> above — it is made for you and shared to your email automatically.' => '\\n<strong>Самый простой:</strong>нажмите<em>«Создать новый лист»</em>выше — он создан для вас и автоматически отправлен на вашу электронную почту.\\n',
  '<strong>Use an existing sheet:</strong> open it in Google Sheets &rarr; Share &rarr; paste' => '\\n<strong>Использовать существующий лист:</strong>откройте его в Google Таблицах → Поделиться → Вставить\\n',
  '&rarr; Editor, then click <em>Browse My Sheets</em> again.' => '\\n→ Редактор, затем снова нажмите<em>«Просмотреть мои таблицы»</em>.\\n',
  'the service account email' => '\\nэлектронная почта сервисного аккаунта\\n',
  'Create a new spreadsheet' => '\\nСоздайте новую таблицу\\n',
  'New spreadsheet title (e.g. Contact form responses)' => '\\nНовое название таблицы (например, ответы в контактной форме)\\n',
  'Your Google email — the sheet is shared here so you can open it' => '\\nВаш адрес электронной почты Google — здесь размещен общий доступ к листу, поэтому вы можете его открыть\\n',
  'Pre-filled from your saved email.' => '\\nПредварительно заполнено из сохраненного электронного письма.\\n',
  'Leave empty only if you don’t need to open the sheet yourself.' => '\\nОставьте пустым, только если вам не нужно открывать лист самостоятельно.\\n',
  'Create Sheet' => '\\nСоздать лист\\n',
  'Creating…' => '\\nСоздание...\\n',
  'Creating spreadsheet…' => '\\nСоздание таблицы...\\n',
  'Sheet created and shared with your email. It’s selected below — click Next to finish.' => '\\nЛист создан и отправлен вам по электронной почте. Он выбран ниже — нажмите «Далее», чтобы закончить.\\n',
  'Sheet created. Tip: add “Your Google email” on the Connections tab so new sheets are shared to you automatically.' => '\\nЛист создан. Совет: добавьте «Ваш адрес электронной почты Google» на вкладке «Подключения», чтобы вам автоматически предоставлялся доступ к новым таблицам.\\n',
  'Open the new sheet' => '\\nОткройте новый лист\\n',
  'Selected:' => '\\nВыбрано:\\n',
  'Loading worksheet tabs…' => '\\nЗагрузка вкладок листа...\\n',
  'Worksheet Tab' => '\\nВкладка «Рабочий лист»\\n',
  'Or type a new tab name (created automatically)' => '\\nИли введите новое имя вкладки (создается автоматически)\\n',
  'Browse My Sheets' => '\\nПросмотреть мои таблицы\\n',
  'Create New Sheet' => '\\nСоздать новый лист\\n',
  'Choose or create a spreadsheet first' => '\\nСначала выберите или создайте таблицу\\n',
  'Please select a service account.' => '\\nПожалуйста, выберите учетную запись службы.\\n',
  'Please choose or create a spreadsheet first.' => '\\nСначала выберите или создайте таблицу.\\n',
  'Enable Sync for this Form' => '\\nВключить синхронизацию для этой формы\\n',
  'Disable to pause without deleting the binding' => '\\nОтключить паузу без удаления привязки\\n',
  'Reading this form’s fields…' => '\\nЧтение полей этой формы...\\n',
  'We couldn’t read this form’s fields automatically, so column mapping isn’t available. Don’t worry — <strong>every submitted field will still be synced automatically</strong>, each in its own column, in submission order. The header row is created and kept up to date for you.' => '\\nМы не смогли автоматически прочитать поля этой формы, поэтому сопоставление столбцов недоступно. Не волнуйтесь —<strong>каждое отправленное поле по-прежнему будет автоматически синхронизироваться</strong>, каждое в своем столбце, в порядке отправки. Строка заголовка создается и постоянно обновляется.\\n',
  'Drag rows (or use ▲▼) to set the <strong>column order</strong>. Rename any <strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C…) shows where each field lands.' => '\\nПеретащите строки (или используйте ▲▼), чтобы установить порядок столбцов<strong></strong>. Переименуйте любой заголовок<strong>в</strong>. Отключите поле, чтобы пропустить его столбец. Буква (A, B, C...) показывает, где находится каждое поле.\\n',
  'Col' => '\\nКол.\\n',
  'Spreadsheet header' => '\\nЗаголовок таблицы\\n',
  'Order / On' => '\\nЗаказать/включить\\n',
  'Refresh fields from form' => '\\nОбновить поля формы\\n',
  'Columns & Field Mapping' => '\\nСтолбцы и сопоставление полей\\n',
  'Submitted time' => '\\nВремя отправки\\n',
  'Submitted At' => '\\nОтправлено в\\n',
  'Column header' => '\\nЗаголовок столбца\\n',
  'Include this field' => '\\nВключите это поле\\n',
  '%d column will be written to the sheet.' . chr(0) . '%d columns will be written to the sheet.' => '[[\' Столбец%dбудет записан на лист.\', \'en\']]' . chr(0) . '[[\' Столбцы%dбудут записаны на лист.\', \'en\']]' . chr(0) . '[[\' Столбцы%dбудут записаны на лист.\', \'en\']]',
  'Sheet Style' => '\\nСтиль листа\\n',
  '(Google theme)' => '\\n(тема Google)\', \'ru\']]',
  'Pick a look for the sheet — colored header, frozen top row and alternating row colors (Google Sheets’ own styling). It’s applied automatically on the first sync, or apply it now.' => '[[\'Выберите внешний вид листа — цветной заголовок, фиксированная верхняя строка и чередующиеся цвета строк (собственный стиль Google Sheets). Оно применяется автоматически при первой синхронизации или примените его сейчас.\\n',
  'Apply style now' => '\\nПримените стиль сейчас\\n',
  'Applying…' => '\\nПодача заявки...\\n',
  'Optional — it also applies on the first submission.' => '\\nНеобязательно — это также применяется при первой отправке.\\n',
  'Spreadsheet:' => '\\nТаблица:\\n',
  'Tab:' => '\\nВкладка:\\n',
  'Columns:' => '\\nСтолбцы:\\n',
  '%d mapped' => '\\n%dсопоставлен\\n',
  'all submitted fields (auto)' => '\\nвсе отправленные поля (авто)\\n',
  'Style:' => '\\nСтиль:\\n',
  'After saving, submit the form once to create the header row and confirm the first sync.' => '\\nПосле сохранения отправьте форму один раз, чтобы создать строку заголовка и подтвердить первую синхронизацию.\\n',
  'Save Binding' => '\\nСохранить привязку\\n',
  'Please choose a spreadsheet first.' => '[[\'Сначала выберите таблицу.\\n',
  'Pick a style first — “None” leaves the sheet unstyled.' => '\\nСначала выберите стиль: при выборе «Нет» лист останется без стиля.\\n',
  'Style applied.' => '\\nСтиль применен.\\n',
  'Please select a form.' => '\\nПожалуйста, выберите форму.\\n',
  'Please choose a spreadsheet.' => '\\nПожалуйста, выберите таблицу.\\n',
  'Binding saved.' => '\\nПривязка сохранена.\\n',
  'Remove this binding? Syncing stops for this form. Your Google Sheet and its data are not deleted.' => '\\nУдалить эту привязку? Синхронизация останавливается для этой формы. Ваш Google Sheet и его данные не удаляются.\\n',
  'Sync removed — your Google Sheet and its data are untouched.' => '\\nСинхронизация удалена — ваш Google Sheet и его данные не будут затронуты.\\n',
  'Remove ALL %d binding? Syncing stops for every form. Your Google Sheets are not deleted.' . chr(0) . 'Remove ALL %d bindings? Syncing stops for every form. Your Google Sheets are not deleted.' => '[[\'Удалить привязку ALL%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.\', \'ru\']]' . chr(0) . '[[\'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.\', \'ru\']]' . chr(0) . '[[\'Удалить ВСЕ привязки%d? Синхронизация останавливается для каждой формы. Ваши Google Таблицы не удалены.\', \'ru\']]',
  'All bindings removed. Your Google Sheets are untouched.' => '\\nВсе привязки удалены. Ваши Google Таблицы не тронуты.\\n',
  'Help & Setup Guide' => '\\nСправка и руководство по установке\\n',
  'Everything you need to connect forms to Google Sheets' => '\\nВсе, что вам нужно для подключения форм к Google Таблицам\\n',
  'Step-by-Step Setup' => '\\nПошаговая настройка\\n',
  'Create or Select a Project' => '\\nСоздать или выбрать проект\\n',
  'Open console.cloud.google.com and log in &rarr; click the Project dropdown (top-left) &rarr; New Project (or pick an existing one) &rarr; enter a name &rarr; Create' => '\\nОткройте console.cloud.google.com и войдите в систему → щелкните раскрывающийся список «Проект» (вверху слева) → «Новый проект» (или выберите существующий) → введите имя → «Создать», «en»]]',
  'Enable both Google APIs' => '\\nВключите оба API Google\\n',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> and <strong>Google Drive API</strong> (both are required — Drive lists and creates the files)' => '\\nAPI и службы → Библиотека → включить<strong>Google Sheets API</strong>и<strong>Google Drive API</strong>(оба обязательны — список дисков и создание файлов)\\n',
  'Create a Service Account' => '\\nСоздайте учетную запись службы\\n',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; enter a name &rarr; Done' => '\\nAPI и службы → Учетные данные → Создать учетные данные → Учетная запись службы → введите имя → Готово\\n',
  'Create a JSON Key' => '\\nСоздайте ключ JSON\\n',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; choose JSON (file downloads automatically)' => '\\nОткройте учетную запись службы → вкладка «Ключи» → «Добавить ключ» → «Создать новый ключ» → выберите JSON (файл загружается автоматически)\\n',
  'Drop the Key File' => '\\nПеретащите файл ключа\\n',
  'Drag the downloaded file into the Connections tab — it is verified automatically and you’ll see a green “Connected” badge' => '\\nПеретащите загруженный файл на вкладку «Подключения» — он будет проверен автоматически, и вы увидите зеленый значок «Подключено».\\n',
  'Add Your Google Email' => '\\nДобавьте свой адрес электронной почты Google\\n',
  'On the Connections tab, fill in “Your Google email” and Save — sheets the plugin creates are then shared to you so they appear in your own Drive' => '\\nНа вкладке «Подключения» заполните «Ваш адрес электронной почты Google» и «Сохранить» — листы, созданные плагином, затем будут доступны вам и появятся на вашем собственном Диске.\\n',
  'Bind a Form (create a sheet)' => '\\nПривязать форму (создать лист)\\n',
  'Form Bindings &rarr; pick a form &rarr; <strong>Create New Sheet</strong> &rarr; Save. No manual sharing needed — this is the easiest path' => '\\nПривязки формы → выберите форму →<strong>Создать новый лист</strong>→ Сохранить. Не требуется предоставлять общий доступ вручную — это самый простой путь\\n',
  '…or use an existing sheet' => '\\n...или используйте существующий лист\\n',
  'Prefer your own sheet? Open it &rarr; Share &rarr; paste the service account email (copy button on its card) &rarr; Editor &rarr; then Browse My Sheets in the wizard' => '\\nПредпочитаете свой собственный лист? Откройте его → Поделиться → вставьте адрес электронной почты сервисного аккаунта (кнопка «копировать» на его карточке) → Редактор → затем «Просмотрите мои таблицы» в мастере», \'en\']]',
  'I created a sheet — where did it go?' => '\\nЯ создал лист — куда он делся?\\n',
  'Service accounts create files in their own hidden Drive. Add “Your Google email” on the Connections tab and the plugin shares every new sheet to you automatically — it then appears under “Shared with me” in your Google Drive. Each sheet also has an “Open” link right in this dashboard.' => '\\nСлужебные аккаунты создают файлы на своем скрытом диске. Добавьте «Ваш адрес электронной почты Google» на вкладке «Подключения», и плагин автоматически предоставит вам каждый новый лист — затем он появится в разделе «Доступно мне» на вашем Google Диске. На каждом листе также есть ссылка «Открыть» прямо на этой панели управления.\\n',
  'Why don’t I see my existing sheet in the picker?' => '\\nПочему я не вижу существующий лист в средстве выбора?\\n',
  'It must be shared with the service account’s email first: open the sheet &rarr; Share &rarr; paste the email (use the copy button on the connection card) &rarr; set Editor &rarr; Share. Then click “Browse My Sheets” again.' => '\\nСначала его необходимо открыть для электронной почты сервисного аккаунта: откройте лист → Поделиться → вставьте письмо (используйте кнопку копирования на карточке подключения) → установите Редактор → Поделиться. Затем снова нажмите «Просмотреть мои таблицы».\\n',
  'Test result: Google API is not enabled.' => '\\nРезультат проверки: Google API не включен.\\n',
  'Open Google Cloud Console for the same project &rarr; APIs &amp; Services &rarr; Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.' => '\\nОткройте консоль Google Cloud для того же проекта → API и сервисы → Библиотека и включите ОБА «API Google Таблиц» и «API Google Диска». Подождите минуту, затем повторите тестирование.\\n',
  'Test result: Access/Permission denied' => '\\nРезультат проверки: доступ/разрешение отклонены\\n',
  'The service account can authenticate but can’t reach that specific spreadsheet. Re-share the sheet with the service account email as Editor, or create a new sheet instead.' => '\\nУчетная запись службы может пройти аутентификацию, но не может получить доступ к этой конкретной таблице. Повторно поделитесь листом с адресом электронной почты сервисного аккаунта в качестве редактора или вместо этого создайте новый лист.\\n',
  'OpenSSL is required.' => '\\nТребуется OpenSSL.\\n',
  'The server is missing the PHP OpenSSL extension used to sign the secure Google request. Ask your host to enable it — no plugin setting can replace it.' => '\\nНа сервере отсутствует расширение PHP OpenSSL, используемое для подписи безопасного запроса Google. Попросите вашего хостера включить его — никакие настройки плагина не смогут его заменить.\\n',
  'Can I connect more than one service account?' => '\\nМогу ли я подключить более одной учетной записи службы?\\n',
  'Yes — drop as many JSON keys as you like in the Connections tab and pick which one each form binding should use.' => '\\nДа — добавьте столько ключей JSON, сколько хотите, на вкладку «Соединения» и выберите, какой из них должна использовать каждая привязка формы.\\n',
  'Does the connection expire?' => '[[\'Срок действия соединения истек?\\n',
  'No. The integration runs entirely on the server using your JSON key — there’s no browser session or login to expire.' => '\\nНет. Интеграция полностью выполняется на сервере с использованием вашего ключа JSON — нет сеанса браузера или входа в систему, срок действия которого истекает.\\n',
  'Can I choose which field goes to which column?' => '\\nМогу ли я выбрать, какое поле относится к какому столбцу?\\n',
  'Yes. In the binding wizard’s <strong>Columns &amp; Fields</strong> step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.' => '\\nДа. На шаге<strong>Columns & Fields</strong>мастера привязки перетащите строки (или используйте ▲▼), чтобы установить порядок, переименуйте каждый заголовок столбца и отключите любое поле, чтобы пропустить его. Значок A/B/C показывает, где именно находится каждое поле.\\n',
  'Can I style the sheet automatically?' => '\\nМожно ли автоматически стилизовать лист?\\n',
  'Yes. The <strong>Style &amp; Save</strong> step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.' => '\\nДа. Шаг<strong>«Стиль и сохранение»</strong>предлагает темы Google-Таблиц (цветной заголовок, фиксированный верхний ряд, чередующиеся цвета строк). Выберите один из них, и он будет применен при первой синхронизации, или нажмите «Применить стиль сейчас».\\n',
  'What if my form fields change later?' => '\\nЧто, если поля моей формы изменятся позже?\\n',
  'New fields are added automatically. In mapped mode, open the Columns step and click “Refresh fields from form” to pull them into the mapping; in “All Form Fields” mode they appear as new columns on the next submission.' => '\\nНовые поля добавляются автоматически. В режиме сопоставления откройте шаг «Столбцы» и нажмите «Обновить поля из формы», чтобы перенести их в сопоставление; в режиме «Все поля формы» они отображаются как новые столбцы при следующей отправке.\\n',
  'What if the tab doesn’t exist yet?' => '\\nЧто делать, если вкладка еще не существует?\\n',
  'It is created automatically the first time a submission is synced.' => '\\nОн создается автоматически при первой синхронизации отправки.\\n',
  'Google Sheet Sync Logs' => '\\nЖурналы синхронизации Google Таблиц\\n',
  'Latest submissions sent to Google Sheets, success or failure' => '\\nПоследние отправленные материалы в Google Таблицы: успешные или неудачные.\\n',
  'Log cleared.' => '\\nЖурнал очищен.\\n',
  'Clear Log' => '\\nОчистить журнал\\n',
  'Clear all logs?' => '\\nОчистить все журналы?\\n',
  'No sync activity yet.' => '\\nСинхронизация пока не выполнена.\\n',
  'Spreadsheet' => '\\nТаблица\\n',
  'Synced' => '\\nсинхронизировано\\n',
  'None (plain)' => '\\nНет (обычный)\\n',
  'Minimal' => '\\nМинимальный\\n',
  'Slate' => '\\nСланец\\n',
  'Sunset' => '\\nЗакат\\n',
  'Grape' => '\\nВиноград\\n',
  '%s is currently unavailable.' => '\\n%sв настоящее время недоступен.\\n',
  'disabled in php.ini: %s' => '\\nотключено в php.ini:%s\\n',
  'not provided by PHP or its required extension: %s' => '\\nне предоставляется PHP или его необходимым расширением:%s\\n',
  '%1$s cannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disable_functions in php.ini.' => '\\n%1$sне может быть запущен, поскольку необходимые функции PHP недоступны (%2$s). Попросите своего хостинг-провайдера включить необходимое расширение PHP или удалить перечисленные функции из Disabled_functions в php.ini.\\n',
  'This add-on is not included in Flux Forms.' => '\\nЭто дополнение не включено в Flux Forms.\\n',
  'Error: server (%s) responded with an invalid request. responded code : %s ' => '\\nОшибка: сервер (%s) ответил неверным запросом. код ответа:%s\\n',
  'Your Easy Form Builder Pro subscription has expired, so this add-on cannot be downloaded.' => '\\nСрок действия вашей подписки на Easy Form Builder Pro истек, поэтому загрузить это дополнение невозможно.\\n',
  'Something went wrong, please refresh the page.' => '\\nЧто-то пошло не так, обновите страницу.\\n',
  'The response attachment could not be verified. Please attach the file again.' => '\\nНе удалось проверить вложение ответа. Пожалуйста, прикрепите файл еще раз.\\n',
  'You do not have permission to update these settings.' => '\\nУ вас нет разрешения на обновление этих настроек.", \'en\']]',
  'Please enter a valid admin email address.' => '\\nПожалуйста, введите действительный адрес электронной почты администратора.\\n',
  'You do not have permission to complete setup.' => '\\nУ вас недостаточно прав для завершения установки.\\n',
  'Invalid email address' => '\\nНеверный адрес электронной почты\\n',
  'Invalid sender email' => '\\nНеверный адрес электронной почты отправителя\\n',
  'The sender email address is not valid.' => '\\nАдрес электронной почты отправителя недействителен.\\n',
  'Email tester service error' => '\\nОшибка службы проверки электронной почты\\n',
  'Could not start email test.' => '\\nНе удалось запустить проверку электронной почты.\\n',
  'Invalid service response' => '\\nНеверный ответ службы\\n',
  'The email tester service returned an invalid response.' => '\\nСлужба проверки электронной почты вернула неверный ответ.\\n',
  'The message never left your website: WordPress reported an error while trying to send it. This is the one case where the fix really is on the WordPress or hosting side - usually an SMTP plugin, or PHP mail disabled by the host.' => '\\nСообщение так и не покинуло ваш сайт: WordPress сообщил об ошибке при попытке его отправки. Это единственный случай, когда исправление действительно происходит на стороне WordPress или хостинга — обычно это плагин SMTP или почта PHP, отключенная хостом.\\n',
  'WordPress could not send the test email. The message never left your website, so nothing was delivered.' => '\\nWordPress не удалось отправить тестовое письмо. Сообщение так и не покинуло ваш сайт, поэтому ничего не было доставлено.\\n',
  'Email test is waiting for delivery confirmation' => '[[\'Проверка электронной почты ожидает подтверждения доставки\\n',
  'WordPress sent the test email. Flux Forms is waiting for the delivery result before marking email as ready.' => '\\nWordPress отправил тестовое письмо. Flux Forms ожидает результата доставки, прежде чем пометить электронное письмо как готовое.\\n',
  'WordPress accepted and sent the test email. Waiting for it to arrive.' => '\\nWordPress принял и отправил тестовое письмо. Ждем его прибытия.\\n',
  'The email tester service returned an invalid JSON response.' => '\\nСлужба проверки электронной почты вернула неверный ответ в формате JSON.\\n',
  'The email tester service could not start the test.' => '\\nСлужбе тестирования электронной почты не удалось запустить тест.\\n',
  'Invalid test hash' => '\\nНеверный хэш теста\\n',
  'The email test hash is not valid.' => '\\nТестовый хеш электронной почты недействителен.\\n',
  'Your site could not connect' => '\\nВаш сайт не смог подключиться\\n',
  'No connection could be opened from your site to our mail testing service. This is usually outbound traffic blocked by your server or its network - some hosts block connections to other countries - rather than a problem with the service. Your hosting provider can confirm it.' => '[[\'Не удалось установить соединение с вашего сайта с нашей службой тестирования почты. Обычно это исходящий трафик, заблокированный вашим сервером или его сетью (некоторые хосты блокируют соединения с другими странами), а не проблема со службой. Ваш хостинг-провайдер может это подтвердить.\\n',
  'Service error' => '\\nОшибка сервиса\\n',
  'The email tester service could not return the result.' => '\\nСлужба проверки электронной почты не может вернуть результат.\\n',
  'The message never left your website. WordPress reported an error while sending, so nothing could be delivered.' => '\\nСообщение никогда не покидало ваш сайт. WordPress сообщил об ошибке при отправке, поэтому доставить ничего не удалось.\\n',
  'The email was sent, but it never arrived' => '\\nПисьмо было отправлено, но так и не пришло\\n',
  'WordPress sent the message successfully, so your site and this plugin did their part. It was lost, delayed or rejected after leaving WordPress - usually the receiving side treated it as spam, or your host never delivered it from the outbound queue.' => '\\nWordPress успешно отправил сообщение, поэтому ваш сайт и этот плагин внесли свой вклад. Оно было потеряно, задержано или отклонено после выхода из WordPress — обычно принимающая сторона считала его спамом, или ваш хост не доставил его из исходящей очереди.\\n',
  'Email test failed' => '\\nПроверка электронной почты не удалась\', \'ru\']]',
  'The email server test could not verify email capability.' => '\\nТестирование сервера электронной почты не смогло проверить возможности электронной почты.\\n',
  'Email capability verified' => '\\nВозможность электронной почты проверена\\n',
  'Server confirmed ability to send emails.' => '\\nСервер подтвердил возможность отправлять электронную почту.\\n',
  'Your emails are being delivered to spam' => '\\nВаши письма попадают в спам\\n',
  'WordPress sent the test email, but delivery has not been confirmed yet.' => '\\nWordPress отправил тестовое письмо, но доставка еще не подтверждена.\\n',
  'Email delivery failed: %s' => '\\nНе удалось доставить электронное письмо:%s\\n',
  'No file was received. Please choose a file and try again.' => '\\nФайл не получен. Пожалуйста, выберите файл и повторите попытку.\\n',
  'The file could not be read. Please try attaching it again.' => '\\nФайл не может быть прочитан. Пожалуйста, попробуйте прикрепить его еще раз.\\n',
  'Enable the Email Notification Feature' => '\\nВключите функцию уведомления по электронной почте\\n',
  'To receive email notifications from your forms, verify your email server by following these steps:' => '\\nЧтобы получать уведомления по электронной почте из ваших форм, подтвердите свой почтовый сервер, выполнив следующие действия:\\n',
  'Go to the <a href="%s" style="font-weight:600;">Flux Forms Panel</a>' => '\\nПерейдите на панель<a href="%s" style="font-weight:600;">Flux Forms</a>\\n',
  'Click Settings from the top menu' => '\\nНажмите «Настройки» в верхнем меню\\n',
  'Select the Email Settings tab' => '\\nВыберите вкладку «Настройки электронной почты».\\n',
  'Click "Check Email Server" and wait for the test to finish' => '\\nНажмите «Проверить сервер электронной почты» и дождитесь завершения теста.\\n',
  'If the score is above 70 — enable the "This site can send emails" switch and save' => '\\nЕсли оценка выше 70 — включите переключатель «Этот сайт может отправлять электронные письма» и сохраните\\n',
  'Otherwise, follow the instructions shown in the test results' => '\\nВ противном случае следуйте инструкциям, указанным в результатах теста.\\n',
  '%s notification' => '\\n Уведомление%s\\n',
  'Disabling this feature may affect the proper functionality of Flux Forms. If you plan to use the %s feature, please ensure it is enabled.' => '\\nОтключение этой функции может повлиять на правильную работу Flux Forms. Если вы планируете использовать функцию%s, убедитесь, что она включена.\\n',
  'Email system is working properly.' => '\\nСистема электронной почты работает правильно.\\n',
  'Your server is able to send emails using the default PHP mail system.' => '\\nВаш сервер может отправлять электронные письма, используя почтовую систему PHP по умолчанию.\', \'en\']]',
  'Email system is not available.' => '\\nСистема электронной почты недоступна.\\n',
  'The PHP mail() function is missing. Your server cannot send emails.' => '\\nФункция PHP mail() отсутствует. Ваш сервер не может отправлять электронную почту.\\n',
  'Email sending is blocked by server settings.' => '\\nОтправка электронной почты заблокирована настройками сервера.\\n',
  'The mail() function is disabled in your server PHP configuration (php.ini).' => '\\nФункция mail() отключена в конфигурации PHP вашего сервера (php.ini).\\n',
  'WordPress mail function not found.' => '\\nФункция почты WordPress не найдена.\\n',
  'The wp_mail() function is missing or not available. WordPress email features may be broken.' => '\\nФункция wp_mail() отсутствует или недоступна. Функции электронной почты WordPress могут быть неработоспособны.\\n',
  'No email handler configured.' => '\\nОбработчик электронной почты не настроен.\\n',
  'Your server has no SMTP host or sendmail path set. Emails may not be delivered.' => '\\nНа вашем сервере не указан хост SMTP или путь отправки почты. Письма могут не доставляться.\\n',
  'Test email could not be sent.' => '\\nНе удалось отправить тестовое письмо.\\n',
  'It seems that your WordPress site could not send a test email. To manually test your email system, go to Flux Forms > Settings > Email Settings tab and click the "Check Email Server" button.' => '\\nПохоже, что ваш сайт WordPress не смог отправить тестовое письмо. Чтобы вручную протестировать систему электронной почты, перейдите на вкладку Flux Forms > Настройки > Настройки электронной почты и нажмите кнопку «Проверить сервер электронной почты».\\n',
  'Invalid email address.' => '\\nНеверный адрес электронной почты.\\n',
  'Please enter a valid admin email address before testing email delivery.' => '\\nПеред проверкой доставки электронной почты введите действительный адрес электронной почты администратора.\\n',
  'Invalid sender email.' => '\\nНеверный адрес электронной почты отправителя.\\n',
  'The sender email address is not valid. Please check your email settings.' => '\\nАдрес электронной почты отправителя недействителен. Пожалуйста, проверьте настройки электронной почты.\\n',
  'Email tester service error.' => '\\nОшибка службы тестера электронной почты.\\n',
  'Flux Forms could not start the email delivery test. Please try again later.' => '\\nFlux Forms не удалось запустить тест доставки электронной почты. Пожалуйста, повторите попытку позже.\\n',
  'Invalid email tester response.' => '\\nНеверный ответ тестера электронной почты.\', \'en\']]',
  'Invalid email test.' => '\\nНеверный тест электронной почты.\\n',
  'The email test identifier is invalid. Please start a new test.' => '\\nИдентификатор теста электронной почты недействителен. Пожалуйста, начните новый тест.\\n',
  'Email tester connection error.' => '\\nОшибка подключения тестера электронной почты.\\n',
  'Flux Forms could not connect to the email tester service.' => '\\nFlux Forms не удалось подключиться к службе проверки электронной почты.\\n',
  'Email delivery test failed.' => '\\nПроверка доставки электронной почты не удалась.\\n',
  'Your emails are arriving in the spam folder.' => '\\nВаши письма попадают в папку «Спам».\\n',
  'The test message was delivered, but its deliverability score is too low to rely on. Sending through SMTP and adding SPF and DKIM records for your domain is what fixes this.' => '\\nТестовое сообщение было доставлено, но его показатель доставляемости слишком низок, чтобы на него можно было положиться. Это решается отправкой через SMTP и добавлением записей SPF и DKIM для вашего домена.\\n',
  'Email delivery test is pending.' => '\\nОжидается проверка доставки электронной почты.\\n',
  'Email Issue' => '\\nПроблема с электронной почтой\\n',
  'Flux Forms Email Warning:' => '\\nПредупреждение по электронной почте Flux Forms:\\n',
  'Plan data is missing.' => '\\nДанные плана отсутствуют.\\n',
  'Invalid plan data format.' => '\\nНеверный формат данных плана.\\n',
  'Invalid plan type.' => '\\nНеверный тип плана.\\n',
  'Please confirm this plan downgrade before continuing.' => '\\nПожалуйста, подтвердите переход на более ранний план, прежде чем продолжить.\\n',
  'Free plan activated - no additional features.' => '\\nБесплатный план активирован — дополнительных функций нет.\\n',
  'Free Plus plan activated with enhanced features.' => '\\nАктивирован план Free Plus с расширенными функциями.\\n',
  'Pro plan activated with existing activation code.' => '\\nПлан Pro активирован с использованием существующего кода активации.\\n',
  'Redirecting to Pro plan purchase page.' => '\\nПеренаправление на страницу покупки плана Pro.\\n',
  'Plan "%s" has been successfully processed.' => '\\nПлан «%s» успешно обработан.\\n',
  'Addon Installation Issue' => '\\nПроблема с установкой аддона\\n',
  'Technical Details' => '\\nТехнические детали\\n',
  'Checked %s' => '\\nПроверено%s\\n',
  'System Ready' => '\\nСистема готова\\n',
  'Checking add-on installation capabilities&hellip;' => '\\nПроверка возможности установки дополнений...\', \'ru\']]',
  'This check runs once after plugin activation. Please refresh the page in a few moments.' => '\\nЭта проверка выполняется один раз после активации плагина. Пожалуйста, обновите страницу через несколько минут.\\n',
  'Some add-ons need a PHP server change' => '\\nНекоторые дополнения требуют смены сервера PHP\\n',
  'Flux Forms has safely paused each affected active add-on, so the rest of the plugin can continue working.' => '\\nFlux Forms безопасно приостановил работу каждого затронутого активного дополнения, чтобы остальная часть плагина могла продолжить работу.\\n',
  '(currently enabled and paused)' => '\\n(в настоящее время включено и приостановлено)\\n',
  '(not enabled)' => '\\n(не включено)\\n',
  'disabled in php.ini:' => '\\nотключено в php.ini:\\n',
  'not provided by PHP or its required extension:' => '[["не предусмотрено PHP или его необходимым расширением:\\n',
  'This usually means the needed PHP extension is not installed, or the function is listed in disable_functions in php.ini. Please ask your hosting provider to enable it, then refresh this page.' => '\\nОбычно это означает, что необходимое расширение PHP не установлено или функция указана в отключении_функций в php.ini. Попросите вашего хостинг-провайдера включить эту функцию, а затем обновите эту страницу.\\n',
  'If you are seeing this message, it is likely for one of these reasons: If you have a caching plugin installed, its settings may need to be reviewed.' => '\\nЕсли вы видите это сообщение, скорее всего, это происходит по одной из следующих причин: Если у вас установлен плагин кеширования, возможно, необходимо просмотреть его настройки.\\n',
  'Please also ensure that you have a stable internet connection and try again.' => '\\nТакже убедитесь, что у вас стабильное подключение к Интернету, и повторите попытку.\\n',
  'Built with %sYT Form%s by %sWordPress form plugin by whitestudio.team%s' => '\\nСоздано с помощью%sYT Form%sот%sПлагин формы WordPress от whitestudio.team%s\\n',
  'Free WordPress form plugin' => '\\nБесплатный плагин форм WordPress\\n',
  'Powered by %1$sYT Form%2$s . %3$sbest Form plugin for Wordpress%4$s.' => '\\nПри поддержке%1$sФорма YT%2$s.%3$sлучший плагин форм для Wordpress%4$s.\\n',
  'Flux Forms WordPress Plugin' => '\\nПлагин Flux Forms для WordPress\\n',
  'This form requires a payment method. Please add one or change the form type.' => '\\nДля этой формы требуется способ оплаты. Добавьте одну или измените тип формы.\\n',
  'Error Monitor' => '\\nМонитор ошибок\\n',
  'WordPress Core' => '\\nЯдро WordPress\\n',
  'Line' => '\\nЛиния\\n',
  'No errors detected' => '\\nОшибок не обнаружено\\n',
  'These errors may interfere with forms built using Flux Forms.' => '\\nЭти ошибки могут помешать работе форм, созданных с использованием Flux Forms.\\n',
  'This panel is only visible to site administrators.' => '\\nЭта панель видна только администраторам сайта.\\n',
  'jQuery Dependency Issue' => '\\njQuery Проблема с зависимостями\\n',
  'jQuery is not properly loaded or available. AJAX and interactive form features may not work correctly.' => '\\njQuery неправильно загружен или недоступен. Функции AJAX и интерактивные формы могут работать неправильно.\\n',
  'WhiteStudio.team' => '\\nWhiteStudio.team\\n',
  'EFB' => '\\nEFB\\n',
  'Flux Forms is a free and powerful WordPress form builder plugin for creating contact forms, payment forms, surveys, registration forms, multi-step forms, file upload forms, electronic signature forms, and audio, video, and screen recording forms, with conditional logic, email notifications, integrations, entry management, and advanced spam protection.' => '[[\'Flux Forms — это бесплатный и мощный плагин для создания форм WordPress для создания контактных форм, форм оплаты, опросов, форм регистрации, многошаговых форм, форм загрузки файлов, форм электронной подписи, а также форм аудио, видео и записи экрана с условной логикой, уведомлениями по электронной почте, интеграцией, управлением записями и расширенной защитой от спама.\\n',
  'WordPress Form Builder Plugin' => '\\nПлагин WordPress Form Builder\\n',
  'WordPress 5.0 or later; PHP 7.0 or later' => '\\nWordPress 5.0 или новее; PHP 7.0 или более поздней версии\\n',
