  'Some plugin files are missing, so the plugin stopped loading to keep your site running. Please reinstall Flux Forms from the Plugins page — your forms, messages, and settings are kept.' => '\\nНекоторые файлы плагина отсутствуют, поэтому плагин перестал загружаться, чтобы ваш сайт продолжал работать. Пожалуйста, переустановите Flux Forms со страницы Плагины — ваши формы, сообщения и настройки сохранятся.\\n',
  'Missing files:' => '\\nОтсутствующие файлы:\\n',
  'Select a form to display from the dropdown below.' => '\\nВыберите форму для отображения из раскрывающегося списка ниже.\\n',
  'Selected Form:' => '\\nВыбранная форма:\\n',
  'Form will be displayed here on the frontend.' => '\\nФорма будет отображаться здесь, во внешнем интерфейсе.\\n',
  'Loading forms&hellip;' => '\\nЗагрузка форм...\\n',
  '📍 Confirmation Code Finder (Tracking Form)' => '[[\'📍 Поиск кода подтверждения (форма отслеживания)\\n',
  'Choose a form to display. The tracking form allows users to find submissions by confirmation code.' => '\\nВыберите форму для отображения. Форма отслеживания позволяет пользователям находить отправленные материалы по коду подтверждения.\\n',
  'Show Form Title' => '\\nПоказать заголовок формы\\n',
  'Container' => '\\nКонтейнер\\n',
  'Border Radius' => '\\nРадиус границы\\n',
  'Box Shadow' => '\\nТень коробки\\n',
  'Select a form from the widget settings panel.' => '\\nВыберите форму на панели настроек виджета.\\n',
  '👈 Use the sidebar to choose a form' => '\\n👈 Используйте боковую панель, чтобы выбрать форму\', \'tr\']]',
  'Selected Form ID:' => '\\nВыбранный идентификатор формы:\\n',
  'The form will appear here on the frontend.' => '\\nФорма появится здесь, в интерфейсе.\\n',
  'Display an Flux Forms form' => '\\nОтображение формы Flux Forms\\n',
  'Display the form name as a heading above the form.' => '\\nОтображение имени формы в виде заголовка над формой.\\n',
  'Extra Class Name' => '\\nДополнительное имя класса\\n',
  'Add custom CSS classes for styling.' => '\\nДобавьте пользовательские классы CSS для стилизации.\', \'en\']]',
  'Design' => '\\nДизайн\\n',
  'CSS' => '\\nCSS\\n',
  'Select a form from the element settings.' => '\\nВыберите форму в настройках элемента.\\n',
  '✏️ Click to edit and choose a form' => '\\n✏️ Нажмите, чтобы отредактировать и выберите форму\\n',
  'Add forms created with Flux Forms' => '[[\'Добавить формы, созданные с помощью Flux Forms\\n',
  'Display Flux Forms forms on your page' => '\\nОтображение форм Flux Forms на вашей странице\\n',
  'Choose the form you want to display' => '\\nВыберите форму, которую хотите отобразить\\n',
  'Please select a form from element settings' => '\\nПожалуйста, выберите форму в настройках элемента\\n',
  'Form: %s (ID: %s)' => '\\nФорма:%s(ID:%s)\\n',
  '📍 Confirmation Code Finder (Tracking)' => '\\n📍 Поиск кода подтверждения (отслеживание)\', \'en\']]',
  '🎨 Flux Forms' => '\\n🎨 Формы потока\\n',
  'Add Flux Forms forms to your page' => '\\nДобавьте формы Flux Forms на свою страницу\\n',
  'Select Form:' => '\\nВыберите форму:\\n',
  'Custom Title (optional):' => '\\nПользовательский заголовок (необязательно):\', \'en\']]',
  'Shortcode:' => '\\nКороткий код:\\n',
  'Run the email check' => '\\nЗапустите проверку электронной почты\\n',
  'The last delivery check scored %s out of 100. Your messages do leave the site, but most mailboxes will file them as spam, so the people filling in your forms will not see them. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => '\\nПоследняя проверка доставки получила оценку%sиз 100. Ваши сообщения покидают сайт, но большинство почтовых ящиков воспринимают их как спам, поэтому люди, заполняющие ваши формы, не увидят их. Это решается отправкой через службу SMTP и добавлением записей SPF и DKIM для вашего домена.\\n',
  'The last delivery check found that your messages do leave the site, but mailboxes file them as spam. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => '\\nПоследняя проверка доставки показала, что ваши сообщения покидают сайт, но почтовые ящики фиксируют их как спам. Это решается отправкой через службу SMTP и добавлением записей SPF и DKIM для вашего домена.\\n',
  'Your form emails are going to the spam folder' => '\\nВаши электронные письма попадают в папку «Спам».\\n',
  'Your form emails are sent, but they are not arriving' => '[[\'Ваши электронные письма отправлены, но не доходят\\n',
  'WordPress sent the last test message successfully, so your site and this plugin did their part - it was lost, delayed or rejected after leaving WordPress. Usually the receiving mailbox treated it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => '\\nWordPress успешно отправил последнее тестовое сообщение, поэтому ваш сайт и этот плагин сделали свое дело — оно было потеряно, задержано или отклонено после выхода из WordPress. Обычно принимающий почтовый ящик воспринимал его как спам, или ваш хост никогда не доставлял его из исходящей очереди. Это решается отправкой через службу SMTP с записями SPF и DKIM для вашего домена.\\n',
  'WordPress cannot send your form emails' => '\\nWordPress не может отправлять электронные письма с формой\\n',
  'The last check could not even hand a message to your mail server: WordPress reported an error while sending, so nothing left the site. An SMTP plugin, or asking your host whether PHP mail is disabled, is where to start.' => '\\nПоследняя проверка даже не смогла передать сообщение на ваш почтовый сервер: WordPress сообщил об ошибке при отправке, поэтому с сайта ничего не ушло. Плагин SMTP или запрос вашего хоста, отключена ли почта PHP, — это то, с чего следует начать.\\n',
  'Your form emails are not being delivered' => '\\nВаши электронные письма не доставляются\', \'ru\']]',
  'The last delivery check could not get a message through, so nothing your forms send is reaching anybody. A hosting server usually sends mail without a trusted signature; sending through an SMTP service is the standard fix.' => '\\nПоследней проверке доставки не удалось доставить сообщение, поэтому никакие отправленные вами формы никому не доходят. Хостинг-сервер обычно отправляет почту без доверенной подписи; отправка через службу SMTP является стандартным решением.\\n',
  'Once Weekly (Flux Forms)' => '\\nОдин раз в неделю (формы Flux)\\n',
  'The weekly email delivery test completed successfully.' => '\\nЕженедельный тест доставки электронной почты успешно завершен.\\n',
  'The weekly email delivery test found an email delivery problem.' => '\\nЕженедельная проверка доставки электронной почты выявила проблему с доставкой электронной почты.\\n',
  'The main WordPress administrator email address is not valid.' => '\\nОсновной адрес электронной почты администратора WordPress недействителен.\\n',
  'Could not start the email delivery test.' => '\\nНе удалось запустить проверку доставки электронной почты.\\n',
  'WordPress sent the automated test email and is waiting for it to arrive.' => '\\nWordPress отправил автоматическое тестовое письмо и ожидает его прибытия.\\n',
  'WordPress could not send the automated test email. The message never left this website.' => '\\nWordPress не удалось отправить автоматическое тестовое письмо. Сообщение никогда не покидало этот сайт.\\n',
  'The email delivery test timed out before confirmation was received.' => '\\nПрежде чем было получено подтверждение, время ожидания проверки доставки электронной почты истекло.\\n',
  'Weekly Flux Forms report for %s' => '\\nЕженедельный отчет Flux Forms для%s\\n',
  'Here is your weekly snapshot for %s.' => '\\nВот ваш еженедельный снимок%s.\\n',
  'Report generated %s' => '[[\'Отчет создан%s\\n',
  'Detailed analysis' => '\\nДетальный анализ\\n',
  'Emails failed' => '\\nЭлектронная почта не отправлена\\n',
  'You can turn these reports off in Flux Forms settings.' => '\\nВы можете отключить эти отчеты в настройках Flux Forms.\\n',
  'The test email was delivered, but its deliverability score is only %1$s out of 100 (below %2$s), so the emails your forms send are very likely to be rejected or filtered as spam.' => '\\nТестовое электронное письмо было доставлено, но его показатель доставляемости составляет только%1$sиз 100 (ниже%2$s), поэтому электронные письма, отправляемые вашими формами, с большой вероятностью будут отклонены или отфильтрованы как спам.\\n',
  'Run the email check so you can be sure the messages your forms send are actually reaching people. The check sends a real message through the new WhiteStudio delivery service and reports back what arrived.' => '\\nЗапустите проверку электронной почты, чтобы быть уверенным, что сообщения, отправляемые вашими формами, действительно доходят до людей. Проверка отправляет реальное сообщение через новую службу доставки WhiteStudio и сообщает о том, что пришло.\\n',
  'Read the guide to sending email through SMTP' => '\\nПрочитайте руководство по отправке электронной почты через SMTP\\n',
  'Delivery has not been scored yet' => '\\nДоставка еще не оценена\\n',
  'WordPress sent your email, but it never arrived' => '\\nWordPress отправил ваше письмо, но оно так и не пришло\\n',
  'WordPress could not send your email' => '\\nWordPress не удалось отправить ваше письмо\', \'ru\']]',
  'We could not confirm your emails are being delivered' => '\\nМы не смогли подтвердить доставку ваших писем.\\n',
  'out of 100' => '\\nиз 100\\n',
  'Your email delivery is healthy' => '\\nДоставка электронной почты работает нормально\\n',
  'Your emails are likely going to spam' => '\\nВаши письма, скорее всего, попадут в спам\\n',
  'Your emails are not reaching anybody' => '\\nВаши письма никому не доходят\\n',
  'grade %s' => '\\nоценка%s\\n',
  'What you should do' => '\\nЧто вам следует делать\\n',
  'A hosting server usually sends mail without a trusted signature, which is what pushes your form emails into the spam folder or stops them arriving at all. The standard fix is to send through an SMTP service.' => '\\nХостинг-сервер обычно отправляет почту без доверенной подписи, что приводит к тому, что ваши электронные письма попадают в папку со спамом или вообще останавливаются. Стандартное решение — отправка через службу SMTP.\\n',
  'Install an SMTP plugin and enter the details of your email service.' => '\\nУстановите плагин SMTP и введите данные своей почтовой службы.\\n',
  'Add the SPF and DKIM records to your domain settings.' => '\\nДобавьте записи SPF и DKIM в настройки вашего домена.\\n',
  'Run the email check again until the score is above %s.' => '\\nЗапустите проверку электронной почты еще раз, пока оценка не превысит%s.\\n',
  'You have %1$s forms: %2$s active and %3$s inactive.' => '\\nУ вас есть формы%1$s:%2$sактивна и%3$sнеактивна.\\n',
  'Renew Flux Forms Pro' => '\\nОбновить формы Flux Pro\\n',
  'Get more from Flux Forms Pro' => '\\nПолучите больше от Flux Forms Pro\\n',
  'Renew your subscription to restore all Pro features and add-ons.' => '\\nОбновите подписку, чтобы восстановить все функции и дополнения Pro.\\n',
  'Unlock premium add-ons, unlimited features and priority support for your forms.' => '\\nРазблокируйте надстройки премиум-класса, неограниченные функции и приоритетную поддержку ваших форм.\\n',
  'Renew Pro' => '\\nОбновить Pro\\n',
  'Email delivery is working' => '\\nДоставка электронной почты работает\\n',
  'The automated Flux Forms email delivery test completed successfully.' => '\\nАвтоматическая проверка доставки электронной почты Flux Forms завершена успешно.\\n',
  'You can attach up to %1$d file here. Please wait about %2$d minutes before trying again.' . chr(0) . 'You can attach up to %1$d files here. Please wait about %2$d minutes before trying again.' => '[[\'Здесь вы можете прикрепить файл%1$d. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.\', \'ru\']]' . chr(0) . '[[\'Здесь вы можете прикрепить до%1$dфайлов. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.\', \'ru\']]' . chr(0) . '[[\'Здесь вы можете прикрепить до%1$dфайлов. Пожалуйста, подождите около%2$dминут, прежде чем повторить попытку.\', \'ru\']]',
  'This file is too large. The maximum size for this field is %s.' => '\\nЭтот файл слишком велик. Максимальный размер этого поля —%s.\\n',
  'This file type is not accepted here. Please attach one of the file types listed on the field.' => '\\nЭтот тип файла здесь не принимается. Прикрепите один из типов файлов, перечисленных в поле.\\n',
  'This file appears to be empty. Please choose a different file.' => '\\nЭтот файл кажется пустым. Пожалуйста, выберите другой файл.\\n',
  'The uploaded file could not be verified. Please attach it again.' => '\\nЗагруженный файл не удалось проверить. Пожалуйста, прикрепите его еще раз.\\n',
  'X-WP-Nonce header is missing' => '\\nЗаголовок X-WP-Nonce отсутствует\\n',
  'Your form session has expired. Please reload the page.' => '\\nСрок вашего сеанса формы истек. Пожалуйста, перезагрузите страницу.\\n',
  'Form ID:' => '\\nИдентификатор формы:\\n',
  'The form will be displayed on the frontend.' => '\\nФорма будет отображена во внешнем интерфейсе.\\n',
  'This link uses an older format. For improved security, new email notifications include updated links.' => '\\nЭта ссылка использует старый формат. Для повышения безопасности новые уведомления по электронной почте включают обновленные ссылки.\\n',
  'It seems that you are the admin of this form. Please log in and try again.' => '\\nПохоже, что вы являетесь администратором этой формы. Пожалуйста, войдите в систему и повторите попытку.\\n',
  'Flux Forms couldn\'t locate the form settings. Please check your settings or contact support for assistance.' => '\\nFlux Forms не удалось найти настройки формы. Пожалуйста, проверьте настройки или обратитесь в службу поддержки за помощью.\\n',
  'Y/m/d \\a\\t g:ia' => '\\nY/m/d \\\\a\\\\t g:ia\\n',
  'Too many attempts. Please wait a few minutes and try again.' => '\\nСлишком много попыток. Пожалуйста, подождите несколько минут и повторите попытку.\\n',
  'The recording upload could not be verified. Please record it again and retry.' => '[[\'Не удалось проверить загрузку записи. Пожалуйста, запишите его еще раз и повторите попытку.\\n',
  'This recording format is not supported. Please record it again.' => '\\nЭтот формат записи не поддерживается. Пожалуйста, запишите это еще раз.\\n',
  'The server could not verify the recording format. Please contact the site administrator.' => '\\nСерверу не удалось проверить формат записи. Пожалуйста, свяжитесь с администратором сайта.\\n',
  'The recording format could not be verified. Please record it again.' => '\\nНе удалось проверить формат записи. Пожалуйста, запишите это еще раз.\\n',
  'The server could not verify the recording duration. Please record it again and try uploading.' => '\\nСерверу не удалось проверить продолжительность записи. Пожалуйста, запишите его еще раз и попробуйте загрузить.\\n',
  'The server could not store the recording. Please try again or contact the site administrator.' => '\\nСерверу не удалось сохранить запись. Пожалуйста, попробуйте еще раз или обратитесь к администратору сайта.\\n',
  'The recording request could not be verified. Please retry.' => '\\nЗапрос на запись не может быть проверен. Пожалуйста, повторите попытку.\', \'ru\']]',
  'The upload request could not be verified. Please try again.' => '\\nЗапрос на загрузку не удалось проверить. Пожалуйста, попробуйте еще раз.\\n',
  'The upload field could not be verified. Please refresh the form and try again.' => '\\nНе удалось проверить поле загрузки. Пожалуйста, обновите форму и повторите попытку.\\n',
  'The response box could not be verified. Reopen the conversation and try again.' => '\\nНе удалось проверить поле ответа. Откройте беседу снова и повторите попытку.\\n',
  'The response attachment could not be secured. Please try again.' => '\\nНе удалось защитить вложение ответа. Пожалуйста, попробуйте еще раз.\\n',
  'Not allowed to respond to this message.' => '\\nНе разрешено отвечать на это сообщение.\\n',
  'Payment Intent ID is missing' => '[[\'Идентификатор платежного намерения отсутствует\\n',
  'persiaPayment' => '\\npersiaPayment\\n',
  'The Email Address Is Not Valid' => '\\nАдрес электронной почты недействителен\\n',
  'The Username Must Contain Only Letters, Numbers And Lowercase letters' => '\\nИмя пользователя должно содержать только буквы, цифры и строчные буквы\', \'en\']]',
  'The Username Must Contain At Least 3 Characters.' => '\\nИмя пользователя должно содержать не менее 3 символов.\\n',
  'The Password Must Contain At Least 8 Characters!' => '\\nПароль должен содержать не менее 8 символов!\\n',
  'The Password Must Contain At Least 1 Number!' => '\\nПароль должен содержать хотя бы 1 цифру!\\n',
